import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { MapPin, Calendar, Users, DollarSign, Heart, Briefcase, Palmtree, User, X, CheckCircle, Plane, Hotel, FileText, Layout, ArrowRight, Sparkles, Map as MapIcon, Navigation, Utensils, Search, Plus, Minus, Locate, Layers, ArrowLeft, Loader2, Compass, List, Globe, ShieldCheck, Database, Clock, Sun, FileJson, ExternalLink, AlertCircle, Car, Play, Star } from 'lucide-react';
import { DreamTripInput, DreamTripResult, TripTheme, UserProfile, GeneratedPlace, Attraction } from '../types';
import { generateDreamTrip } from '../services/mockSmartPlan';
import { generateCityGuide, generateCountryDatabase, fetchRouteData } from '../services/geminiService';
import { CURRENCIES, formatCurrency } from '../services/data';
import { CityGuideSection } from './CityGuideModal';
import { CountryGuideSection } from './CountryGuideModal';

interface SmartPlanProps {
  isOpen: boolean;
  onClose: () => void;
  userProfile: UserProfile;
  onSave: (plan: DreamTripResult) => void;
  initialPlan?: DreamTripResult | null;
  onAddToWishlist: (attraction: Attraction | Attraction[]) => void;
  onRemoveFromWishlist: (id: string | string[]) => void;
  itinerary: Attraction[];
}

// --- Live Map Picker Component ---
const MapPicker: React.FC<{ 
  label: string; 
  value: { name: string; lat: number; lng: number } | null;
  onChange: (val: { name: string; lat: number; lng: number }) => void;
}> = ({ label, value, onChange }) => {
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [tempLocation, setTempLocation] = useState<{ name: string; lat: number; lng: number } | null>(value);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerInstanceRef = useRef<any>(null);

  // Initialize Map
  useEffect(() => {
    if (isMapOpen && mapContainerRef.current && !mapInstanceRef.current) {
      const L = (window as any).L;
      if (!L) return;

      const startLat = value?.lat || 20;
      const startLng = value?.lng || 0;
      const startZoom = value ? 12 : 2;

      const map = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: true }).setView([startLat, startLng], startZoom);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Esri, Maxar, Earthstar Geographics', maxZoom: 19 }).addTo(map);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}').addTo(map);

      if (value) markerInstanceRef.current = L.marker([value.lat, value.lng]).addTo(map);

      map.on('click', async (e: any) => {
        const { lat, lng } = e.latlng;
        if (markerInstanceRef.current) markerInstanceRef.current.remove();
        markerInstanceRef.current = L.marker([lat, lng]).addTo(map);
        setTempLocation({ name: 'Selected Location', lat, lng });
        try {
           const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
           const data = await res.json();
           const displayName = data.address?.city || data.address?.town || data.address?.village || data.name || "Custom Location";
           setTempLocation({ name: displayName, lat, lng });
        } catch (err) { console.error("Reverse geocode failed", err); }
      });
      mapInstanceRef.current = map;
    }
    return () => { if (!isMapOpen && mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null; markerInstanceRef.current = null; } };
  }, [isMapOpen]);

  useEffect(() => { if (isMapOpen) { setTempLocation(value); setSearchQuery(value?.name || ''); } }, [isMapOpen, value]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    const L = (window as any).L;
    try {
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}&limit=1`);
        const data = await response.json();
        if (data && data.length > 0) {
            const { lat, lon, display_name } = data[0];
            const latitude = parseFloat(lat);
            const longitude = parseFloat(lon);
            const shortName = display_name.split(',')[0];
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 13);
                if (markerInstanceRef.current) markerInstanceRef.current.remove();
                markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
            }
            setTempLocation({ name: shortName, lat: latitude, lng: longitude });
        } else { alert("Location not found."); }
    } catch (err) { alert("Connection error."); } finally { setIsSearching(false); }
  };

  const handleZoom = (delta: number) => { if (mapInstanceRef.current) mapInstanceRef.current.setZoom(mapInstanceRef.current.getZoom() + delta); };
  const handleLocateMe = () => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition((pos) => {
              const { latitude, longitude } = pos.coords;
              if (mapInstanceRef.current) {
                  mapInstanceRef.current.setView([latitude, longitude], 14);
                  const L = (window as any).L;
                  if (markerInstanceRef.current) markerInstanceRef.current.remove();
                  markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
                  fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`).then(res => res.json()).then(data => { const name = data.address?.city || data.address?.town || "My Location"; setTempLocation({ name, lat: latitude, lng: longitude }); });
              }
          });
      }
  };
  const confirmLocation = () => { if (tempLocation) { onChange(tempLocation); setIsMapOpen(false); } };

  return (
    <>
      <div className="space-y-2"><label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">{label}</label><button type="button" onClick={() => setIsMapOpen(true)} className={`w-full p-5 rounded-xl border text-left flex items-center justify-between transition-all hover:shadow-md ${value ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800' : 'bg-gray-50 dark:bg-slate-800 border-gray-200 dark:border-slate-700'}`}><div className="flex items-center gap-3"><div className={`p-2 rounded-full ${value ? 'bg-blue-500 text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400'}`}><MapPin size={18} /></div><div><p className={`font-bold text-sm ${value ? 'text-blue-900 dark:text-blue-100' : 'text-gray-500'}`}>{value ? value.name : 'Select Location'}</p>{value && <p className="text-[10px] text-blue-600 dark:text-blue-300 opacity-70">{value.lat.toFixed(4)}, {value.lng.toFixed(4)}</p>}</div></div><div className="bg-gray-100 dark:bg-slate-700 p-2 rounded-full"><ArrowRight size={16} className="text-gray-400" /></div></button></div>
      {isMapOpen && createPortal(<div className="fixed inset-0 z-[100] bg-black/95 flex flex-col animate-fade-in"><div className="absolute top-4 left-4 right-4 z-[500] flex items-center gap-3"><button onClick={() => setIsMapOpen(false)} className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-xl text-gray-700 dark:text-white hover:bg-gray-50 transition-colors border border-gray-200 dark:border-slate-700"><ArrowLeft size={20} /></button><form onSubmit={handleSearch} className="flex-1 relative shadow-xl"><input value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search places..." className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 rounded-full outline-none text-slate-900 dark:text-white border border-gray-200 dark:border-slate-700 shadow-sm" /><Search className="absolute left-4 top-3.5 text-gray-400" size={20} /></form></div><div className="w-full h-full relative"><div ref={mapContainerRef} className="w-full h-full" /><div className="absolute bottom-32 right-4 flex flex-col gap-3 z-[400]"><button onClick={handleLocateMe} className="p-3.5 bg-white dark:bg-slate-800 rounded-full shadow-xl text-blue-600 hover:bg-gray-50 border border-gray-200 dark:border-slate-700"><Locate size={22} /></button><div className="flex flex-col bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-200 dark:border-slate-700 overflow-hidden"><button onClick={() => handleZoom(1)} className="p-3.5 hover:bg-gray-50 text-gray-700 dark:text-white border-b border-gray-100 dark:border-slate-700"><Plus size={22} /></button><button onClick={() => handleZoom(-1)} className="p-3.5 hover:bg-gray-50 text-gray-700 dark:text-white"><Minus size={22} /></button></div></div>{tempLocation && (<div className="absolute bottom-0 left-0 right-0 p-4 bg-white dark:bg-slate-900 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.2)] z-[500] animate-slide-up"><div className="w-12 h-1.5 bg-gray-300 dark:bg-slate-700 rounded-full mx-auto mb-4" /><div className="flex justify-between items-start mb-4 px-2"><div><h3 className="text-xl font-bold text-slate-900 dark:text-white mb-1">{tempLocation.name}</h3><p className="text-sm text-gray-500 dark:text-gray-400">{tempLocation.lat.toFixed(4)}, {tempLocation.lng.toFixed(4)}</p></div><div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-full"><MapPin className="text-blue-600 dark:text-blue-400" size={24} /></div></div><button onClick={confirmLocation} className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-600/20 transition-transform active:scale-[0.98] flex items-center justify-center gap-2">Set Location</button></div>)}</div></div>, document.body)}
    </>
  );
};

export const SmartPlan: React.FC<SmartPlanProps> = ({ isOpen, onClose, userProfile, onSave, initialPlan, onAddToWishlist, onRemoveFromWishlist, itinerary }) => {
  const [step, setStep] = useState<'input' | 'loading' | 'result'>('input');
  const [tripResult, setTripResult] = useState<DreamTripResult | null>(null);
  const [activeTab, setActiveTab] = useState('Overview');
  const [activeSection, setActiveSection] = useState<'planner' | 'city' | 'country'>('planner');
  const currency = CURRENCIES.find(c => c.code === userProfile.currency) || CURRENCIES[0];

  // Form State
  const [tripInput, setTripInput] = useState<DreamTripInput>({
    departureLocation: null,
    destinationLocation: null,
    startDate: '',
    endDate: '',
    budget: 5000,
    travelers: 1,
    theme: 'Relax'
  });

  const getTodayString = () => new Date().toISOString().split('T')[0];

  useEffect(() => {
    if (isOpen) {
      if (initialPlan) {
        setTripResult(initialPlan);
        setStep('result');
        setActiveTab('Overview');
        setActiveSection('planner');
      } else {
        if (step === 'result' && !tripResult) { 
             setStep('input');
        }
      }
    }
  }, [isOpen, initialPlan]);

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if (!tripInput.departureLocation || !tripInput.destinationLocation || !tripInput.startDate || !tripInput.endDate) {
      alert("Please fill in all required fields.");
      return;
    }
    setStep('loading');
    try {
      const result = await generateDreamTrip(tripInput);
      setTripResult(result);
      setStep('result');
      setActiveTab('Overview');
    } catch (error) {
      console.error(error);
      setStep('input');
      alert("Failed to generate plan. Please try again.");
    }
  };

  const handleSaveAndClose = () => {
      if (tripResult) {
          onSave(tripResult);
          onClose();
      }
  };

  const reset = () => {
    setStep('input');
    setTripResult(null);
    setTripInput({
        departureLocation: null,
        destinationLocation: null,
        startDate: '',
        endDate: '',
        budget: 5000,
        travelers: 1,
        theme: 'Relax'
    });
    setActiveTab('Overview');
  };

  const tabs = ['Overview', 'Itinerary', 'Accommodation', 'Visa Requirements'];

  const navItems = [
      { id: 'planner', label: 'AI Planner', icon: Plane, color: 'text-blue-600', activeColor: 'text-blue-600 border-blue-600' },
      { id: 'city', label: 'AI City Guide', icon: Sparkles, color: 'text-purple-600', activeColor: 'text-purple-600 border-purple-600' },
      { id: 'country', label: 'AI Country Guide', icon: Database, color: 'text-emerald-600', activeColor: 'text-emerald-600 border-emerald-600' }
  ];

  return (
    <div className="fixed inset-0 z-50 overflow-hidden bg-slate-900/90 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-950 w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl border border-gray-200 dark:border-slate-800 overflow-hidden flex flex-col md:flex-row animate-fade-in-up">

        {/* Sidebar Navigation */}
        <div className="w-full md:w-64 bg-gray-50 dark:bg-slate-900 border-b md:border-b-0 md:border-r border-gray-200 dark:border-slate-800 flex flex-col shrink-0">
            <div className="p-6 border-b border-gray-200 dark:border-slate-800 flex justify-between items-center md:block">
                <div className="flex items-center gap-2">
                    <div className="bg-indigo-600 p-1.5 rounded-lg shadow-lg shadow-indigo-500/20">
                        <Layers size={20} className="text-white" />
                    </div>
                    <div>
                        <h2 className="font-bold text-slate-900 dark:text-white leading-none">AI Assistant</h2>
                        <p className="text-[10px] text-gray-500 dark:text-gray-400 mt-0.5">Travel Dashboard</p>
                    </div>
                </div>
                <button onClick={onClose} className="md:hidden p-2 text-gray-500"><X size={24} /></button>
            </div>

            <div className="flex-1 p-4 overflow-y-auto">
                <div className="space-y-1">
                    {navItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => setActiveSection(item.id as any)}
                            className={`w-full flex items-center gap-3 p-4 rounded-xl transition-all text-base font-medium ${activeSection === item.id ? 'bg-white dark:bg-slate-800 shadow-sm text-slate-900 dark:text-white border border-gray-200 dark:border-slate-700' : 'text-gray-500 dark:text-gray-400 hover:bg-white/50 dark:hover:bg-slate-800/50'}`}
                        >
                            <div className={`p-2 rounded-lg ${activeSection === item.id ? 'bg-gray-100 dark:bg-slate-700 ' + item.color : 'bg-transparent text-gray-400'}`}>
                                <item.icon size={20} />
                            </div>
                            {item.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="p-4 border-t border-gray-200 dark:border-slate-800 hidden md:block">
                <button onClick={onClose} className="w-full flex items-center justify-center gap-2 p-3 text-sm font-medium text-gray-500 hover:text-gray-900 dark:hover:text-white transition-colors">
                    <ArrowLeft size={16} /> Back to App
                </button>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col min-w-0 bg-white dark:bg-slate-950 relative overflow-hidden">

            {/* Top Bar for Mobile/Tablet */}
            <div className="md:hidden border-b border-gray-200 dark:border-slate-800 shrink-0 z-20">
                <div className="px-4 py-3 flex gap-4 overflow-x-auto scrollbar-hide">
                    {navItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => setActiveSection(item.id as any)}
                            className={`flex items-center gap-2 py-4 px-2 border-b-2 transition-all whitespace-nowrap text-base font-bold ${
                                activeSection === item.id 
                                ? `${item.activeColor} dark:text-white` 
                                : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200'
                            }`}
                        >
                            <div className={`p-2 rounded-lg ${activeSection === item.id ? 'bg-gray-100 dark:bg-slate-800' : ''}`}>
                                <item.icon size={20} className={activeSection === item.id ? item.color : 'text-gray-400'} />
                            </div>
                            {item.label}
                        </button>
                    ))}
                </div>
            </div>

            {/* Planner Section */}
            {activeSection === 'planner' && (
                <div className="flex flex-col h-full">
                    <div className="p-6 border-b border-gray-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-950 sticky top-0 z-20">
                        <h2 className="text-xl font-bold text-slate-900 dark:text-white">Smart Trip Planner</h2>
                        {step === 'result' && <button onClick={reset} className="px-4 py-2 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-full transition-colors">New Trip</button>}
                    </div>
                    <div className="flex-1 overflow-y-auto bg-slate-50 dark:bg-slate-900/50">
                        {step === 'input' && (
                            <div className="p-8 max-w-3xl mx-auto space-y-8 w-full">
                                <div className="text-center space-y-2 mb-6">
                                    <h3 className="text-3xl font-bold text-slate-900 dark:text-white">Design your dream trip</h3>
                                    <p className="text-gray-500 dark:text-gray-400">Tell us where and when, and we'll handle the magic.</p>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <MapPicker label="Departure City" value={tripInput.departureLocation} onChange={(loc) => setTripInput({...tripInput, departureLocation: loc})} />
                                    <MapPicker label="Destination" value={tripInput.destinationLocation} onChange={(loc) => setTripInput({...tripInput, destinationLocation: loc})} />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Travel Dates</label>
                                        <div className="flex items-center gap-2">
                                            <div className="relative w-full">
                                                <input 
                                                    type={tripInput.startDate ? "date" : "text"} 
                                                    placeholder="dd-mm-yyyy"
                                                    onFocus={(e) => (e.target.type = "date")}
                                                    onBlur={(e) => { if(!e.target.value) e.target.type = "text"; }}
                                                    min={getTodayString()} 
                                                    className={`w-full p-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium ${tripInput.startDate ? 'text-slate-900 dark:text-white' : 'text-gray-400'}`} 
                                                    value={tripInput.startDate} 
                                                    onChange={(e) => setTripInput({...tripInput, startDate: e.target.value})} 
                                                />
                                            </div>
                                            <ArrowRight className="text-gray-400 shrink-0" />
                                            <div className="relative w-full">
                                                <input 
                                                    type={tripInput.endDate ? "date" : "text"}
                                                    placeholder="dd-mm-yyyy" 
                                                    onFocus={(e) => (e.target.type = "date")}
                                                    onBlur={(e) => { if(!e.target.value) e.target.type = "text"; }}
                                                    min={tripInput.startDate || getTodayString()} 
                                                    className={`w-full p-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium ${tripInput.endDate ? 'text-slate-900 dark:text-white' : 'text-gray-400'}`} 
                                                    value={tripInput.endDate} 
                                                    onChange={(e) => setTripInput({...tripInput, endDate: e.target.value})} 
                                                />
                                            </div>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Details</label>
                                        <div className="flex gap-4">
                                            <div className="flex-1 relative"><Users className="absolute left-4 top-4 text-gray-400" size={18} /><select className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 dark:text-white appearance-none font-medium" value={tripInput.travelers} onChange={(e) => setTripInput({...tripInput, travelers: parseInt(e.target.value)})}>{[1,2,3,4,5,6].map(n => <option key={n} value={n}>{n} Traveler{n > 1 ? 's' : ''}</option>)}</select></div>
                                            <div className="flex-1 relative"><span className="absolute left-4 top-4 text-gray-400 font-bold text-lg flex items-center justify-center w-5 h-5 pointer-events-none">{currency.symbol}</span><input type="number" className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 dark:text-white font-medium" placeholder={`Budget`} value={tripInput.budget} onChange={(e) => setTripInput({...tripInput, budget: parseInt(e.target.value)})} /></div>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Trip Theme</label>
                                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                                        {['Relax', 'Adventure', 'Romantic', 'Family', 'Cultural'].map((theme) => (
                                            <button key={theme} onClick={() => setTripInput({...tripInput, theme: theme as TripTheme})} className={`p-5 rounded-xl border flex flex-col items-center justify-center gap-3 transition-all ${tripInput.theme === theme ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-500 text-indigo-700 dark:text-indigo-300 shadow-sm' : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-700 text-gray-500 hover:border-indigo-300'}`}>
                                                {theme === 'Relax' && <Palmtree size={28} />}
                                                {theme === 'Adventure' && <Compass size={28} />}
                                                {theme === 'Romantic' && <Heart size={28} />}
                                                {theme === 'Family' && <Users size={28} />}
                                                {theme === 'Cultural' && <Briefcase size={28} />}
                                                <span className="text-sm font-bold">{theme}</span>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <button onClick={handleGenerate} className="w-full py-5 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white rounded-2xl font-bold text-xl shadow-xl shadow-indigo-500/30 transition-all transform hover:scale-[1.01] flex items-center justify-center gap-3"><Sparkles className="animate-pulse" /> Generate My Plan</button>
                            </div>
                        )}
                        {step === 'loading' && (
                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white dark:bg-slate-950 z-30">
                                <div className="relative"><div className="w-24 h-24 border-4 border-indigo-100 dark:border-slate-800 rounded-full"></div><div className="absolute top-0 left-0 w-24 h-24 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div><Plane className="absolute inset-0 m-auto text-indigo-600 animate-pulse" size={32} /></div><h3 className="mt-8 text-xl font-bold text-slate-900 dark:text-white">Curating your experience...</h3><p className="text-gray-500 dark:text-gray-400 mt-2">Finding best flights and hidden gems.</p>
                            </div>
                        )}
                        {step === 'result' && tripResult && (
                            <div className="flex flex-col h-full">
                                <div className="bg-white dark:bg-slate-900 p-6 pb-0 shadow-sm z-10">
                                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
                                        <div><div className="flex items-center gap-2 mb-1"><h1 className="text-2xl font-black text-slate-900 dark:text-white">{tripResult.destination}</h1><span className="px-2 py-0.5 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300 rounded text-xs font-bold uppercase">{tripInput.theme} Trip</span></div><p className="text-sm text-gray-500">{tripResult.dates} • {tripResult.travelers} Travelers</p></div>
                                        <div className="text-right"><p className="text-xs text-gray-500 uppercase font-bold">Total Est. Cost</p><p className="text-2xl font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(tripResult.totalEstimatedCost, userProfile.currency)}</p></div>
                                    </div>
