                                            <button onClick={handleSaveAndClose} className="w-full py-4 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-blue-500/30 transition-all flex items-center justify-center gap-2">{initialPlan ? 'Back to My Plans' : 'Confirm & Book Trip'} <ArrowRight size={20} /></button>
