                                    {activeTab === 'Itinerary' && (<div className="max-w-3xl mx-auto animate-fade-in"><h3 className="font-bold text-xl text-slate-900 dark:text-white mb-6 flex items-center gap-2"><Layout className="text-indigo-500" size={24} /> Daily Schedule</h3><div className="relative border-l-2 border-gray-200 dark:border-slate-700 ml-4 space-y-8">{tripResult.itinerary.map((day, i) => (<div key={i} className="relative pl-8"><div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-indigo-500 ring-4 ring-white dark:ring-slate-950"></div><div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow"><div className="flex justify-between items-start mb-4"><div><h4 className="font-bold text-lg text-slate-900 dark:text-white">Day {day.day}: {day.title}</h4><p className="text-sm text-gray-500">{day.date}</p></div></div><div className="space-y-3">{day.activities.map((act, j) => (<div key={j} className="flex gap-4 p-3 rounded-xl bg-slate-50 dark:bg-slate-700/30"><div className="w-10 h-10 rounded-full bg-white dark:bg-slate-700 flex items-center justify-center shrink-0 shadow-sm text-gray-500">{act.icon === 'travel' && <Navigation size={18} className="text-blue-500" />}{act.icon === 'food' && <Utensils size={18} className="text-orange-500" />}{act.icon === 'activity' && <MapIcon size={18} className="text-emerald-500" />}</div><div><div className="flex items-center gap-2 mb-0.5"><span className="text-xs font-bold bg-gray-200 dark:bg-slate-600 px-1.5 py-0.5 rounded text-gray-700 dark:text-gray-300">{act.time}</span><h5 className="font-bold text-sm text-slate-800 dark:text-slate-200">{act.name}</h5></div><p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed">{act.description}</p></div></div>))}</div></div></div>))}</div></div>)}
                                    {activeTab === 'Accommodation' && (<div className="max-w-3xl mx-auto animate-fade-in"><div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-slate-900 dark:text-white mb-6 flex items-center gap-2"><Hotel className="text-orange-500" size={24} /> Selected Hotel</h3><div className="rounded-2xl overflow-hidden border border-gray-100 dark:border-slate-700 mb-6"><div className="h-64 w-full relative"><img src={tripResult.hotel.image} className="w-full h-full object-cover" alt="Hotel" /><div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-sm font-bold shadow-sm flex items-center gap-1 text-slate-800"><Heart size={14} className="text-red-500 fill-red-500" /> {tripResult.hotel.rating}</div></div><div className="p-6"><h4 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">{tripResult.hotel.name}</h4><p className="text-sm text-gray-500 mb-4 flex items-center gap-2"><MapPin size={16} /> {tripResult.hotel.address}</p><div className="mb-6"><h5 className="text-xs font-bold text-gray-500 uppercase mb-2">Amenities</h5><div className="flex flex-wrap gap-2">{tripResult.hotel.amenities.map(am => (<span key={am} className="text-xs bg-gray-100 dark:bg-slate-700 px-3 py-1.5 rounded-lg text-gray-700 dark:text-gray-300 border border-gray-200 dark:border-slate-600">{am}</span>))}</div></div><div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-slate-700"><div><p className="text-xs text-gray-400 uppercase font-bold">Price Per Night</p><p className="text-xl font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(tripResult.hotel.pricePerNight, userProfile.currency)}</p></div><a href={tripResult.hotel.website} target="_blank" rel="noopener noreferrer" onClick={(e) => e.stopPropagation()} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl text-sm font-bold transition-colors shadow-lg shadow-indigo-500/20">View Rooms & Book</a></div></div></div></div></div>)}
                                    {activeTab === 'Visa Requirements' && (<div className="max-w-3xl mx-auto animate-fade-in"><div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-xl text-slate-900 dark:text-white mb-6 flex items-center gap-2"><ShieldCheck className="text-purple-500" size={24} /> Entry Requirements</h3><div className={`p-4 rounded-xl mb-6 flex items-center gap-4 ${tripResult.visa.required ? 'bg-orange-50 dark:bg-orange-900/20 border border-orange-100 dark:border-orange-800' : 'bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800'}`}><div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${tripResult.visa.required ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}>{tripResult.visa.required ? <Briefcase size={24} /> : <CheckCircle size={24} />}</div><div><p className={`font-bold ${tripResult.visa.required ? 'text-orange-800 dark:text-orange-200' : 'text-green-800 dark:text-green-200'}`}>{tripResult.visa.type}</p><p className="text-sm text-gray-600 dark:text-gray-400">{tripResult.visa.required ? 'Please allow sufficient time for processing.' : 'You can travel with your valid passport.'}</p></div></div><div className="space-y-6"><div><h4 className="font-bold text-sm text-gray-900 dark:text-white uppercase tracking-wide mb-3">Processing Time</h4><p className="text-gray-600 dark:text-gray-300 bg-gray-50 dark:bg-slate-700/50 p-3 rounded-lg inline-block border border-gray-200 dark:border-slate-600">{tripResult.visa.processingTime}</p></div>{tripResult.visa.required && (<div><h4 className="font-bold text-sm text-gray-900 dark:text-white uppercase tracking-wide mb-3">Documents Checklist</h4><ul className="grid grid-cols-1 md:grid-cols-2 gap-3">{tripResult.visa.checklist.map((item, idx) => (<li key={idx} className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-slate-700/30 rounded-xl border border-gray-100 dark:border-slate-600"><div className="w-5 h-5 rounded-full border-2 border-gray-300 dark:border-slate-500" /><span className="text-sm text-gray-700 dark:text-gray-300">{item}</span></li>))}</ul></div>)}</div><div className="mt-8 pt-6 border-t border-gray-100 dark:border-slate-700"><p className="text-xs text-gray-400 italic flex items-center gap-1"><ShieldCheck size={12} /> Information provided as a guide only. Verify with official embassies.</p></div></div></div>)}
                                </div>
