ay-100 dark:border-slate-600"><div className="w-5 h-5 rounded-full border-2 border-gray-300 dark:border-slate-500" /><span className="text-sm text-gray-700 dark:text-gray-300">{item}</span></li>))}</ul></div>)}</div><div className="mt-8 pt-6 border-t border-gray-100 dark:border-slate-700"><p className="text-xs text-gray-400 italic flex items-center gap-1"><ShieldCheck size={12} /> Information provided as a guide only. Verify with official embassies.</p></div></div></div>)}
