  onRemoveFromWishlist: (id: string | string[]) => void;
  itinerary: Attraction[];
}

// --- Live Map Picker Component ---
const MapPicker: React.FC<{ 
  label: string; 
  value: { name: string; lat: number; lng: number } | null;
  onChange: (val: { name: string; lat: number; lng: number }) => void;
}> = ({ label, value, onChange }) => {
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [tempLocation, setTempLocation] = useState<{ name: string; lat: number; lng: number } | null>(value);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerInstanceRef = useRef<any>(null);

  // Initialize Map
  useEffect(() => {
    if (isMapOpen && mapContainerRef.current && !mapInstanceRef.current) {
      const L = (window as any).L;
      if (!L) return;

      const startLat = value?.lat || 20;
      const startLng = value?.lng || 0;
      const startZoom = value ? 12 : 2;

      const map = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: true }).setView([startLat, startLng], startZoom);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Esri, Maxar, Earthstar Geographics', maxZoom: 19 }).addTo(map);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}').addTo(map);

      if (value) markerInstanceRef.current = L.marker([value.lat, value.lng]).addTo(map);

      map.on('click', async (e: any) => {
        const { lat, lng } = e.latlng;
        if (markerInstanceRef.current) markerInstanceRef.current.remove();
        markerInstanceRef.current = L.marker([lat, lng]).addTo(map);
        setTempLocation({ name: 'Selected Location', lat, lng });
        try {
           const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
           const data = await res.json();
           const displayName = data.address?.city || data.address?.town || data.address?.village || data.name || "Custom Location";
           setTempLocation({ name: displayName, lat, lng });
        } catch (err) { console.error("Reverse geocode failed", err); }
      });
      mapInstanceRef.current = map;
    }
    return () => { if (!isMapOpen && mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null; markerInstanceRef.current = null; } };
  }, [isMapOpen]);

  useEffect(() => { if (isMapOpen) { setTempLocation(value); setSearchQuery(value?.name || ''); } }, [isMapOpen, value]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    const L = (window as any).L;
    try {
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}&limit=1`);
        const data = await response.json();
        if (data && data.length > 0) {
            const { lat, lon, display_name } = data[0];
            const latitude = parseFloat(lat);
            const longitude = parseFloat(lon);
            const shortName = display_name.split(',')[0];
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 13);
                if (markerInstanceRef.current) markerInstanceRef.current.remove();
                markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
            }
            setTempLocation({ name: shortName, lat: latitude, lng: longitude });
        } else { alert("Location not found."); }
    } catch (err) { alert("Connection error."); } finally { setIsSearching(false); }
  };

  const handleZoom = (delta: number) => { if (mapInstanceRef.current) mapInstanceRef.current.setZoom(mapInstanceRef.current.getZoom() + delta); };
  const handleLocateMe = () => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition((pos) => {
              const { latitude, longitude } = pos.coords;
              if (mapInstanceRef.current) {
                  mapInstanceRef.current.setView([latitude, longitude], 14);
                  const L = (window as any).L;
                  if (markerInstanceRef.current) markerInstanceRef.current.remove();
                  markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
                  fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`).then(res => res.json()).then(data => { const name = data.address?.city || data.address?.town || "My Location"; setTempLocation({ name, lat: latitude, lng: longitude }); });
              }
          });
      }
  };
  const confirmLocation = () => { if (tempLocation) { onChange(tempLocation); setIsMapOpen(false); } };

  return (
    <>
      <div className="space-y-2"><label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">{label}</label><button type="button" onClick={() => setIsMapOpen(true)} className={`w-full p-5 rounded-xl border text-left flex items-center justify-between transition-all hover:shadow-md ${value ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800' : 'bg-gray-50 dark:bg-slate-800 border-gray-200 dark:border-slate-700'}`}><div className="flex items-center gap-3"><div className={`p-2 rounded-full ${value ? 'bg-blue-500 text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400'}`}><MapPin size={18} /></div><div><p className={`font-bold text-sm ${value ? 'text-blue-900 dark:text-blue-100' : 'text-gray-500'}`}>{value ? value.name : 'Select Location'}</p>{value && <p className="text-[10px] text-blue-600 dark:text-blue-300 opacity-70">{value.lat.toFixed(4)}, {value.lng.toFixed(4)}</p>}</div></div><div className="bg-gray-100 dark:bg-slate-700 p-2 rounded-full"><ArrowRight size={16} className="text-gray-400" /></div></button></div>
      {isMapOpen && createPortal(<div className="fixed inset-0 z-[100] bg-black/95 flex flex-col animate-fade-in"><div className="absolute top-4 left-4 right-4 z-[500] flex items-center gap-3"><button onClick={() => setIsMapOpen(false)} className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-xl text-gray-700 dark:text-white hover:bg-gray-50 transition-colors border border-gray-200 dark:border-slate-700"><ArrowLeft size={20} /></button><form onSubmit={handleSearch} className="flex-1 relative shadow-xl"><input value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search places..." className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 rounded-full outline-none text-slate-900 dark:text-white border border-gray-200 dark:border-slate-700 shadow-sm" /><Search className="absolute left-4 top-3.5 text-gray-400" size={20} /></form></div><div className="w-full h-full relative"><div ref={mapContainerRef} className="w-full h-full" /><div className="absolute bottom-32 right-4 flex flex-col gap-3 z-[400]"><button onClick={handleLocateMe} className="p-3.5 bg-white dark:bg-slate-800 rounded-full shadow-xl text-blue-600 hover:bg-gray-50 border border-gray-200 dark:border-slate-700"><Locate size={22} /></button><div className="flex flex-col bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-200 dark:border-slate-700 overflow-hidden"><button onClick={() => handleZoom(1)} className="p-3.5 hover:bg-gray-50 text-gray-700 dark:text-white border-b border-gray-100 dark:border-slate-700"><Plus size={22} /></button><button onClick={() => handleZoom(-1)} className="p-3.5 hover:bg-gray-50 text-gray-700 dark:text-white"><Minus size={22} /></button></div></div>{tempLocation && (<div className="absolute bottom-0 left-0 right-0 p-4 bg-white dark:bg-slate-900 rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.2)] z-[500] animate-slide-up"><div className="w-12 h-1.5 bg-gray-300 dark:bg-slate-700 rounded-full mx-auto mb-4" /><div className="flex justify-between items-start mb-4 px-2"><div><h3 className="text-xl font-bold text-slate-900 dark:text-white mb-1">{tempLocation.name}</h3><p className="text-sm text-gray-500 dark:text-gray-400">{tempLocation.lat.toFixed(4)}, {tempLocation.lng.toFixed(4)}</p></div><div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-full"><MapPin className="text-blue-600 dark:text-blue-400" size={24} /></div></div><button onClick={confirmLocation} className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-600/20 transition-transform active:scale-[0.98] flex items-center justify-center gap-2">Set Location</button></div>)}</div></div>, document.body)}
    </>
  );
};

export const SmartPlan: React.FC<SmartPlanProps> = ({ isOpen, onClose, userProfile, onSave, initialPlan, onAddToWishlist, onRemoveFromWishlist, itinerary }) => {
