import React, { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, Camera, Star, AlertTriangle, User, Mail, Phone, MapPin, Save, Plus, MessageSquare, Image, Map as MapIcon, ArrowRight, Search, ArrowLeft, Locate, Minus, Link as LinkIcon, Calendar, Clock, Briefcase, CreditCard, CheckSquare, ExternalLink, Check, Loader2 } from 'lucide-react';
