// Advanced Map Picker with Satellite View & Search
const MapPicker: React.FC<{ 
  label: string; 
  value: { name: string; lat: number; lng: number } | null;
  onChange: (val: { name: string; lat: number; lng: number }) => void;
}> = ({ label, value, onChange }) => {
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [tempLocation, setTempLocation] = useState<{ name: string; lat: number; lng: number } | null>(value);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerInstanceRef = useRef<any>(null);

  // Initialize Map
  useEffect(() => {
    if (isMapOpen && mapContainerRef.current && !mapInstanceRef.current) {
      const L = (window as any).L;
      if (!L) return;

      // Default to World View or Selected Location
      const startLat = value?.lat || 20;
      const startLng = value?.lng || 0;
      const startZoom = value ? 12 : 2;

      const map = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([startLat, startLng], startZoom);

      // Esri World Imagery (Satellite)
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
        attribution: 'Esri, Maxar, Earthstar Geographics',
        maxZoom: 19
      }).addTo(map);

      // Esri Reference Labels (Hybrid Overlay)
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}').addTo(map);

      // Add Marker if value exists
      if (value) {
        markerInstanceRef.current = L.marker([value.lat, value.lng]).addTo(map);
      }

      // Click Handler
      map.on('click', async (e: any) => {
        const { lat, lng } = e.latlng;

        // Update Marker
        if (markerInstanceRef.current) markerInstanceRef.current.remove();
        markerInstanceRef.current = L.marker([lat, lng]).addTo(map);

        // Reverse Geocode to get name (optional visual feedback)
        setTempLocation({ name: 'Selected Location', lat, lng }); // Optimistic update

        try {
           const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
           const data = await res.json();
           const displayName = data.address?.city || data.address?.town || data.address?.village || data.name || "Custom Location";
           setTempLocation({ name: displayName, lat, lng });
        } catch (err) {
           console.error("Reverse geocode failed", err);
        }
      });

      mapInstanceRef.current = map;
    }

    // Cleanup
    return () => {
      if (!isMapOpen && mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
        markerInstanceRef.current = null;
      }
    };
  }, [isMapOpen]);

  // Sync value when modal opens
  useEffect(() => {
    if (isMapOpen) {
      setTempLocation(value);
      setSearchQuery(value?.name || '');
    }
  }, [isMapOpen, value]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    const L = (window as any).L;

    try {
        // Using Nominatim for Geocoding
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}&limit=1`);
        const data = await response.json();

        if (data && data.length > 0) {
            const { lat, lon, display_name } = data[0];
            const latitude = parseFloat(lat);
            const longitude = parseFloat(lon);

            // Extract a shorter name
            const shortName = display_name.split(',')[0];

            // Update Map
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 13);

                if (markerInstanceRef.current) markerInstanceRef.current.remove();
                markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
            }

            setTempLocation({ name: shortName, lat: latitude, lng: longitude });
        } else {
            alert("Location not found. Try a different name.");
        }
    } catch (err) {
        console.error("Search failed", err);
        alert("Connection error. Please try again.");
    } finally {
        setIsSearching(false);
    }
  };

  const handleZoom = (delta: number) => {
    if (mapInstanceRef.current) {
      mapInstanceRef.current.setZoom(mapInstanceRef.current.getZoom() + delta);
    }
  };

  const handleLocateMe = () => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition((pos) => {
              const { latitude, longitude } = pos.coords;
              if (mapInstanceRef.current) {
                  mapInstanceRef.current.setView([latitude, longitude], 14);
                  const L = (window as any).L;
                  if (markerInstanceRef.current) markerInstanceRef.current.remove();
                  markerInstanceRef.current = L.marker([latitude, longitude]).addTo(mapInstanceRef.current);

                  // Fetch name
                  fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`)
                   .then(res => res.json())
                   .then(data => {
                       const name = data.address?.city || data.address?.town || "My Location";
                       setTempLocation({ name, lat: latitude, lng: longitude });
                   });
              }
          });
      }
  };

  const confirmLocation = () => {
    if (tempLocation) {
      onChange(tempLocation);
      setIsMapOpen(false);
    }
  };

  return (
    <>
      <div className="space-y-1.5">
         <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">{label}</label>
         <button 
           type="button"
           onClick={() => setIsMapOpen(true)}
           className={`w-full p-4 rounded-xl border text-left flex items-center justify-between transition-all hover:shadow-md ${value ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800' : 'bg-gray-50 dark:bg-slate-800 border-gray-200 dark:border-slate-700'}`}
         >
            <div className="flex items-center gap-3">
               <div className={`p-2 rounded-full ${value ? 'bg-blue-500 text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400'}`}>
                  <MapPin size={18} />
               </div>
               <div>
                  <p className={`font-bold text-sm ${value ? 'text-blue-900 dark:text-blue-100' : 'text-gray-500'}`}>
                    {value ? value.name : 'Select Location on Map'}
                  </p>
                  {value && <p className="text-[10px] text-blue-600 dark:text-blue-300 opacity-70">{value.lat.toFixed(4)}, {value.lng.toFixed(4)}</p>}
               </div>
            </div>
            <div className="bg-gray-100 dark:bg-slate-700 p-2 rounded-full">
                <ArrowRight size={16} className="text-gray-400" />
            </div>
         </button>
      </div>

      {isMapOpen && createPortal(
        <div className="fixed inset-0 z-[100] bg-black/95 flex flex-col animate-fade-in">
           {/* Top Bar */}
           <div className="absolute top-4 left-4 right-4 z-[500] flex items-center gap-3">
              <button onClick={() => setIsMapOpen(false)} className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-xl text-gray-700 dark:text-white hover:bg-gray-50 transition-colors border border-gray-200 dark:border-slate-700">
                 <ArrowLeft size={20} />
              </button>
              <form onSubmit={handleSearch} className="flex-1 relative shadow-xl">
                 <input 
                   value={searchQuery}
                   onChange={(e) => setSearchQuery(e.target.value)}
                   placeholder="Search places..."
