export const SearchView: React.FC<ViewProps & { query: string; setQuery: (q: string) => void }> = ({ navigate, query, setQuery, userProfile }) => {
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [isListening, setIsListening] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const t = (key: string) => getTranslation(userProfile.language, key);

  const categories = [
    { id: 'All', label: 'All' },
    { id: 'Top Rated', label: 'Top Rated' },
    { id: 'Landmark', label: 'Landmarks' },
    { id: 'Museum', label: 'Museums' },
    { id: 'History', label: 'History' },
    { id: 'Free', label: 'Free' }
  ];

  const filtered = MOCK_DB.attractions.filter(a => {
    const matchesQuery = a.name.toLowerCase().includes(query.toLowerCase()) || 
                         MOCK_DB.cities.find(c => c.id === a.cityId)?.name.toLowerCase().includes(query.toLowerCase());

    let matchesCategory = true;
    if (selectedCategory === 'Top Rated') matchesCategory = a.rating >= 4.8;
    else if (selectedCategory === 'Free') matchesCategory = a.price === 'Free';
    else if (selectedCategory !== 'All') matchesCategory = a.category === selectedCategory;

    return matchesQuery && matchesCategory;
  });

  const handleVoiceSearch = () => {
    if ('webkitSpeechRecognition' in window) {
        const recognition = new (window as any).webkitSpeechRecognition();
        recognition.lang = 'en-US';
        recognition.onstart = () => setIsListening(true);
        recognition.onend = () => setIsListening(false);
        recognition.onerror = (event: any) => {
             setIsListening(false);
             if (event.error === 'not-allowed' || event.error === 'permission-denied') {
                 setShowSettings(true);
             }
        };
        recognition.onresult = (event: any) => {
            const transcript = event.results[0][0].transcript;
            setQuery(transcript);
        };
        recognition.start();
    } else {
        alert("Voice search is not supported in this browser.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 pb-20 md:pb-0">
       <div className="bg-white dark:bg-slate-800 sticky top-0 z-30 shadow-sm pb-2">
           <div className="max-w-7xl mx-auto flex items-center gap-3 p-3">
               <button onClick={() => navigate('home')} className="p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-full md:hidden text-gray-700 dark:text-gray-200"><ChevronLeft size={24} /></button>
               <div className="flex-1 relative flex items-center">
                   <Search className="absolute left-3 top-3.5 text-gray-400" size={18} />
                   <input 
                    type="text" 
                    value={query} 
                    onChange={(e) => setQuery(e.target.value)} 
                    className="w-full bg-gray-100 dark:bg-slate-700 dark:text-white rounded-lg pl-10 pr-20 py-2.5 text-sm focus:outline-none transition-all focus:ring-2 focus:ring-blue-500/20" 
                    placeholder={t('search_placeholder')} 
                   />
                   <div className="absolute right-2 top-1.5 flex items-center">
                       {query && (
                         <button onClick={() => setQuery('')} className="p-2 text-gray-400 hover:text-gray-600">
                           <span className="sr-only">Clear</span>
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                             <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                           </svg>
                         </button>
                       )}
                       <button onClick={handleVoiceSearch} className={`p-2 rounded-full transition-colors ${isListening ? 'bg-red-100 text-red-600' : 'text-gray-400 hover:text-blue-500 hover:bg-gray-200 dark:hover:bg-slate-600'}`}>
                           <Mic size={18} />
                       </button>
                   </div>
               </div>
           </div>

           <div className="max-w-7xl mx-auto px-3 overflow-x-auto scrollbar-hide">
             <div className="flex gap-2 pb-2">
               {categories.map(cat => (
                 <button 
                    key={cat.id}
                    onClick={() => setSelectedCategory(cat.id)}
                    className={`px-4 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-all duration-200 border ${
                        selectedCategory === cat.id 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-md shadow-blue-500/20' 
                        : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-gray-200 dark:border-slate-600 hover:border-blue-400 dark:hover:border-blue-400 hover:text-blue-500'
                    }`}
                 >
                    {cat.label}
                 </button>
               ))}
             </div>
           </div>
       </div>

       <div className="max-w-7xl mx-auto px-3 py-3">
         <div className="flex justify-between items-center mb-3">
            <h2 className="text-lg font-semibold text-gray-800 dark:text-white">{filtered.length} {t('results')}</h2>
            {selectedCategory !== 'All' && (
                <span className="text-xs font-medium px-2 py-1 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-300 rounded-md">
                    {t('filtered_by')}: {categories.find(c => c.id === selectedCategory)?.label}
                </span>
            )}
         </div>

         {filtered.length === 0 ? (
             <div className="text-center py-20">
                 <div className="bg-gray-100 dark:bg-slate-800 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4">
                     <Search className="text-gray-400" size={32} />
                 </div>
                 <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-1">{t('no_places_found')}</h3>
                 <p className="text-gray-500 dark:text-gray-400">{t('adjust_search')}</p>
                 <button onClick={() => {setQuery(''); setSelectedCategory('All')}} className="mt-4 text-blue-600 font-medium hover:underline">{t('clear_filters')}</button>
             </div>
         ) : (
             <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-3">
               {filtered.map(attr => (
                 <div key={attr.id} onClick={() => navigate('attraction', { id: attr.id })} className="group cursor-pointer flex flex-col gap-2">
                   <div className="relative aspect-square overflow-hidden rounded-2xl bg-gray-100 dark:bg-slate-800">
                     <ImageWithFallback src={attr.image} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" alt={attr.name} />
                   </div>
                   <div>
                     <h3 className="font-bold text-sm md:text-base text-gray-900 dark:text-white leading-tight truncate">{attr.name}</h3>
                     <p className="text-xs md:text-sm text-gray-500 dark:text-gray-400 truncate">
                        {MOCK_DB.cities.find(c => c.id === attr.cityId)?.country}
                     </p>
                   </div>
                 </div>
               ))}
             </div>
         )}
       </div>
       <SettingsModal isOpen={showSettings} onClose={() => setShowSettings(false)} type="privacy" />
    </div>
  );
};

export const AttractionDetailView: React.FC<ViewProps & { id: string; addToItinerary: (a: Attraction | Attraction[]) => void; saved: boolean, openEditModal: () => void; removeFromItinerary: (id: string | string[]) => void }> = ({ navigate, id, addToItinerary, saved, openEditModal, userProfile, removeFromItinerary }) => {
    const attr = MOCK_DB.attractions.find(a => a.id === id);
    const [summary, setSummary] = useState('');
    const [loading, setLoading] = useState(false);
    const [showAllAccommodations, setShowAllAccommodations] = useState(false);
    const [showAllRestaurants, setShowAllRestaurants] = useState(false);
    const [copySuccess, setCopySuccess] = useState(false);
    const t = (key: string) => getTranslation(userProfile.language, key);

    if (!attr) return <div className="p-8 text-center text-gray-500">Attraction not found</div>;
    const city = MOCK_DB.cities.find(c => c.id === attr.cityId);

    const getLocalCurrency = (country?: string) => {
      if (!country) return 'USD';
      const map: Record<string, string> = {
        'France': 'EUR', 'Italy': 'EUR', 'Spain': 'EUR', 'Greece': 'EUR', 'Netherlands': 'EUR',
        'USA': 'USD', 'UK': 'GBP', 'Japan': 'JPY', 'India': 'INR', 'Australia': 'AUD',
        'China': 'CNY', 'UAE': 'AED', 'Brazil': 'BRL', 'Egypt': 'EGP', 'Peru': 'PEN', 'Turkey': 'TRY'
      };
      return map[country] || 'USD';
    };

    const handleGenerate = async () => {
        setLoading(true);
        const text = await generateAttractionSummary(attr.name, city?.name || '');
        setSummary(text);
        setLoading(false);
    };

    const handleShare = async () => {
        const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(attr.name)}`;
        const shareText = `Check out ${attr.name} in ${city?.name}!`;

        if (navigator.share) {
            try {
                await navigator.share({
                    title: attr.name,
                    text: shareText,
                    url: mapUrl
                });
            } catch (err) {
                console.log('Error sharing:', err);
            }
        } else {
            try {
                await navigator.clipboard.writeText(`${shareText} ${mapUrl}`);
                setCopySuccess(true);
                setTimeout(() => setCopySuccess(false), 2000);
            } catch (err) {
                alert(`${shareText}\n${mapUrl}`);
            }
        }
    };

    const cityAttractions = MOCK_DB.attractions.filter(a => a.cityId === attr.cityId && a.id !== attr.id).sort((a, b) => b.rating - a.rating).slice(0, 3);
    const allCityAccommodations = MOCK_DB.accommodations.filter(a => a.cityId === attr.cityId);
    const allCityRestaurants = MOCK_DB.restaurants.filter(r => r.cityId === attr.cityId);
    const displayAccommodations = showAllAccommodations ? allCityAccommodations : allCityAccommodations.slice(0, 2);
    const displayRestaurants = showAllRestaurants ? allCityRestaurants : allCityRestaurants.slice(0, 2);

    const toggleSave = () => {
      if (saved) {
        removeFromItinerary(attr.id);
      } else {
        addToItinerary(attr);
      }
    };

    return (
      <div className="min-h-screen bg-white dark:bg-slate-900 pb-20">
        <div className="relative h-[40vh] md:h-[50vh]">
          <ImageWithFallback src={attr.image} className="w-full h-full object-cover" alt={attr.name} />
          <button onClick={() => navigate('search')} className="absolute top-4 left-4 bg-blue-600 p-3 rounded-full text-white hover:bg-blue-700 transition-colors shadow-lg z-10"><ChevronLeft size={24} /></button>
          <div className="absolute bottom-0 left-0 right-0 p-6 text-white max-w-5xl mx-auto bg-gradient-to-t from-black/80 to-transparent">
            <h1 className="text-3xl md:text-5xl font-bold mb-2">{attr.name}</h1>
            <div className="flex items-center gap-4 text-sm text-gray-200">
              <span className="flex items-center gap-1"><Star className="text-yellow-400 fill-current" size={16} /> {attr.rating}</span>
              <span className="flex items-center gap-1"><MapPin size={16} /> {city?.name}</span>
            </div>
          </div>
        </div>
        <div className="max-w-5xl mx-auto px-4 md:px-6 py-4 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="md:col-span-2 space-y-4">
             {attr.gallery && attr.gallery.length > 0 && (
               <section><h2 className="text-xl font-bold text-gray-900 dark:text-white mb-3">{t('photos')}</h2><div className="grid grid-cols-2 gap-3">{attr.gallery.map((img, idx) => (<ImageWithFallback key={idx} src={img} className="rounded-lg w-full h-40 object-cover shadow-sm hover:scale-105 transition-transform" alt={`${attr.name} gallery ${idx + 1}`} />))}</div></section>
             )}
             <section className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-800">
                <div className="flex justify-between items-start mb-3"><div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-300"><Sparkles size={20} className="fill-current" /><h3 className="font-bold text-lg">Go Pro AI Insight</h3></div>{!summary && (<button onClick={handleGenerate} disabled={loading} className="text-xs bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-300 px-3 py-1.5 rounded-full font-medium shadow-sm hover:shadow transition-all disabled:opacity-50">{loading ? t('generating') : t('ai_summary')}</button>)}</div>
               {loading ? (<div className="animate-pulse space-y-2"><div className="h-4 bg-indigo-200 dark:bg-indigo-800/50 rounded w-3/4"></div><div className="h-4 bg-indigo-200 dark:bg-indigo-800/50 rounded w-full"></div></div>) : summary ? (<div className="prose dark:prose-invert text-lg font-medium leading-relaxed text-slate-800 dark:text-slate-200">{summary}<div className="mt-3 text-xs text-indigo-400 flex items-center gap-1 font-normal"><Wand2 size={12} /> {t('generated_by')}</div></div>) : null}
             </section>
             <p className="text-gray-600 dark:text-gray-300 text-lg leading-relaxed">{attr.description}</p>
             <div className="bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-2xl p-4 shadow-sm space-y-4 md:hidden">
               <div className="space-y-4 mb-2"><h3 className="font-bold text-gray-900 dark:text-white">{t('visitor_info')}</h3><div className="space-y-3 text-sm text-gray-600 dark:text-gray-300"><div className="flex gap-3 items-start"><Compass size={18} className="text-blue-500 shrink-0 mt-0.5" /><span>{attr.address}</span></div><div className="flex gap-3 items-center"><Calendar size={18} className="text-blue-500 shrink-0" /><span>{attr.hours}</span></div><div className="flex gap-3 items-center"><Ticket size={18} className="text-blue-500 shrink-0" /><span>{attr.priceValue === 0 ? 'Free Entry' : formatCurrency(attr.priceValue, userProfile.currency)}</span></div></div></div>
               <button onClick={openEditModal} className="w-full bg-emerald-600 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2"><Plane size={18}/> {t('plan_trip')}</button>
               <button onClick={toggleSave} className={`w-full py-3 rounded-xl font-bold border flex items-center justify-center gap-2 ${saved ? 'bg-red-50 dark:bg-red-900/20 text-red-600 border-red-200 dark:border-red-900/50' : 'bg-blue-600 text-white'}`}>{saved ? <><Trash2 size={18} /> {t('remove')}</> : t('add_wishlist')}</button>
               <div className="grid grid-cols-3 gap-3 pt-2">
                   <a href={attr.website} target="_blank" rel="noopener noreferrer" className="flex flex-col items-center justify-center gap-1 border border-gray-300 dark:border-slate-600 rounded-xl py-3 hover:bg-gray-50 dark:hover:bg-slate-700 transition-colors text-gray-700 dark:text-gray-300 font-medium"><ExternalLink size={20} className="mb-1" /> <span className="text-sm leading-tight text-center">Visit<br/>Website</span></a>
                   <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(attr.name)}&t=k`} target="_blank" rel="noopener noreferrer" className="flex flex-col items-center justify-center gap-1 border border-gray-300 dark:border-slate-600 rounded-xl py-3 hover:bg-gray-50 dark:hover:bg-slate-700 transition-colors text-gray-700 dark:text-gray-300 font-medium"><MapIcon size={20} className="mb-1" /> <span className="text-sm leading-tight text-center">View on<br/>Map</span></a>
                   <button onClick={handleShare} className="flex flex-col items-center justify-center gap-1 border border-gray-300 dark:border-slate-600 rounded-xl py-3 hover:bg-gray-50 dark:hover:bg-slate-700 transition-colors text-gray-700 dark:text-gray-300 font-medium">
                       {copySuccess ? <CheckCircle size={20} className="mb-1 text-emerald-500" /> : <Share2 size={20} className="mb-1" />}
                       <span className="text-sm leading-tight text-center">{copySuccess ? t('copied') : t('share')}</span>
                   </button>
               </div>
             </div>
