export const AttractionDetailView: React.FC<ViewProps & { id: string; addToItinerary: (a: Attraction | Attraction[]) => void; saved: boolean, openEditModal: () => void; removeFromItinerary: (id: string | string[]) => void }> = ({ navigate, id, addToItinerary, saved, openEditModal, userProfile, removeFromItinerary }) => {
    const attr = MOCK_DB.attractions.find(a => a.id === id);
    const [summary, setSummary] = useState('');
    const [loading, setLoading] = useState(false);
    const [showAllAccommodations, setShowAllAccommodations] = useState(false);
    const [showAllRestaurants, setShowAllRestaurants] = useState(false);
    const [copySuccess, setCopySuccess] = useState(false);
    const t = (key: string) => getTranslation(userProfile.language, key);

    if (!attr) return <div className="p-8 text-center text-gray-500">Attraction not found</div>;
    const city = MOCK_DB.cities.find(c => c.id === attr.cityId);

    const getLocalCurrency = (country?: string) => {
      if (!country) return 'USD';
      const map: Record<string, string> = {
        'France': 'EUR', 'Italy': 'EUR', 'Spain': 'EUR', 'Greece': 'EUR', 'Netherlands': 'EUR',
        'USA': 'USD', 'UK': 'GBP', 'Japan': 'JPY', 'India': 'INR', 'Australia': 'AUD',
        'China': 'CNY', 'UAE': 'AED', 'Brazil': 'BRL', 'Egypt': 'EGP', 'Peru': 'PEN', 'Turkey': 'TRY'
      };
      return map[country] || 'USD';
    };

    const handleGenerate = async () => {
        setLoading(true);
        const text = await generateAttractionSummary(attr.name, city?.name || '');
        setSummary(text);
        setLoading(false);
    };

    const handleShare = async () => {
        const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(attr.name)}`;
        const shareText = `Check out ${attr.name} in ${city?.name}!`;

        if (navigator.share) {
            try {
                await navigator.share({
                    title: attr.name,
                    text: shareText,
                    url: mapUrl
                });
            } catch (err) {
                console.log('Error sharing:', err);
            }
        } else {
            try {
                await navigator.clipboard.writeText(`${shareText} ${mapUrl}`);
                setCopySuccess(true);
                setTimeout(() => setCopySuccess(false), 2000);
            } catch (err) {
                alert(`${shareText}\n${mapUrl}`);
            }
        }
    };

    const cityAttractions = MOCK_DB.attractions.filter(a => a.cityId === attr.cityId && a.id !== attr.id).sort((a, b) => b.rating - a.rating).slice(0, 3);
    const allCityAccommodations = MOCK_DB.accommodations.filter(a => a.cityId === attr.cityId);
    const allCityRestaurants = MOCK_DB.restaurants.filter(r => r.cityId === attr.cityId);
    const displayAccommodations = showAllAccommodations ? allCityAccommodations : allCityAccommodations.slice(0, 2);
    const displayRestaurants = showAllRestaurants ? allCityRestaurants : allCityRestaurants.slice(0, 2);

    const toggleSave = () => {
      if (saved) {
        removeFromItinerary(attr.id);
      } else {
        addToItinerary(attr);
      }
    };

    return (
      <div className="min-h-screen bg-white dark:bg-slate-900 pb-20">
        <div className="relative h-[40vh] md:h-[50vh]">
          <ImageWithFallback src={attr.image} className="w-full h-full object-cover" alt={attr.name} />
          <button onClick={() => navigate('search')} className="absolute top-4 left-4 bg-blue-600 p-3 rounded-full text-white hover:bg-blue-700 transition-colors shadow-lg z-10"><ChevronLeft size={24} /></button>
          <div className="absolute bottom-0 left-0 right-0 p-6 text-white max-w-5xl mx-auto bg-gradient-to-t from-black/80 to-transparent">
            <h1 className="text-3xl md:text-5xl font-bold mb-2">{attr.name}</h1>
            <div className="flex items-center gap-4 text-sm text-gray-200">
              <span className="flex items-center gap-1"><Star className="text-yellow-400 fill-current" size={16} /> {attr.rating}</span>
              <span className="flex items-center gap-1"><MapPin size={16} /> {city?.name}</span>
            </div>
          </div>
        </div>
        <div className="max-w-5xl mx-auto px-4 md:px-6 py-4 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="md:col-span-2 space-y-4">
             {attr.gallery && attr.gallery.length > 0 && (
               <section><h2 className="text-xl font-bold text-gray-900 dark:text-white mb-3">{t('photos')}</h2><div className="grid grid-cols-2 gap-3">{attr.gallery.map((img, idx) => (<ImageWithFallback key={idx} src={img} className="rounded-lg w-full h-40 object-cover shadow-sm hover:scale-105 transition-transform" alt={`${attr.name} gallery ${idx + 1}`} />))}</div></section>
