export const AccommodationDetailView: React.FC<ViewProps & { id: string }> = ({ navigate, id, userProfile }) => {
    const acc = MOCK_DB.accommodations.find(a => a.id === id);
    const t = (key: string) => getTranslation(userProfile.language, key);
    if (!acc) return <div className="p-8 text-center text-gray-500">Accommodation not found</div>;
    const getAmenityIcon = (text: string) => {
        const lower = text.toLowerCase();
        if (lower.includes('wifi')) return <Wifi size={18} />;
        if (lower.includes('food') || lower.includes('breakfast') || lower.includes('tea')) return <Utensils size={18} />;
        if (lower.includes('room') || lower.includes('bed')) return <Bed size={18} />;
        if (lower.includes('center') || lower.includes('view')) return <Compass size={18} />;
        if (lower.includes('pool') || lower.includes('spa')) return <Sparkles size={18} />;
        return <Info size={18} />;
    };
    return (
        <div className="min-h-screen bg-white dark:bg-slate-900 pb-20 md:pb-0">
            <div className="relative h-64 md:h-80 w-full">
                <ImageWithFallback src={acc.image} alt={acc.name} className="w-full h-full object-cover" />
                <button onClick={() => navigate('attraction', { id: MOCK_DB.attractions.find(a => a.cityId === acc.cityId)?.id || 'home' })} className="absolute top-4 left-4 bg-blue-600 p-3 rounded-full text-white shadow-lg z-10 flex items-center justify-center"><ChevronLeft size={24} /></button>
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent md:hidden" /><div className="absolute bottom-4 left-4 text-white md:hidden"><h1 className="text-2xl font-bold">{acc.name}</h1><p className="text-sm opacity-90">{acc.type} • {acc.rating} Stars</p></div>
            </div>
            <div className="max-w-4xl mx-auto px-4 py-3 md:-mt-12 relative z-10">
                <div className="bg-white dark:bg-slate-800 rounded-2xl p-4 shadow-lg border border-gray-100 dark:border-slate-700">
                    <div className="hidden md:flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-4"><div><span className="inline-block px-3 py-1 bg-orange-100 text-orange-600 rounded-full text-xs font-bold uppercase tracking-wider mb-2">{acc.type}</span><h1 className="text-3xl font-bold text-slate-900 dark:text-white mb-1">{acc.name}</h1><div className="flex items-center gap-1 text-yellow-500 font-bold text-sm"><Star size={16} fill="currentColor" /> {acc.rating} Rating</div></div><div className="text-right md:text-right w-full md:w-auto flex flex-row md:flex-col justify-between items-center md:items-end border-t md:border-t-0 border-gray-100 dark:border-slate-700 pt-4 md:pt-0"><div className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{formatCurrency(acc.priceValue, userProfile.currency)}</div><div className="text-sm text-gray-500 dark:text-gray-400">{t('per_night')}</div></div></div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                       <div><h3 className="font-bold text-lg mb-4 text-slate-900 dark:text-white">{t('about_place')}</h3><p className="text-gray-600 dark:text-gray-300 leading-relaxed">Experience world-class service and comfort at {acc.name}. Located perfectly for exploring the city, this {acc.type.toLowerCase()} offers exceptional amenities and a unique atmosphere.</p><div className="mt-6"><h4 className="font-bold text-sm text-slate-900 dark:text-white mb-3">{t('amenities')}</h4><div className="grid grid-cols-2 gap-3 mb-4">{acc.amenities?.map((am, i) => (<div key={i} className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">{getAmenityIcon(am)} {am}</div>))}</div><div className="flex items-center gap-2 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-100 dark:border-blue-800/50"><Users size={16} className="text-blue-600 dark:text-blue-400" /><span className="text-sm font-medium text-slate-700 dark:text-slate-300">{t('per_person').replace('approx. ', 'Approx. ')}</span></div></div></div>
                       <div className="bg-gray-50 dark:bg-slate-700/50 p-4 rounded-xl space-y-4 h-fit"><h3 className="font-bold text-slate-900 dark:text-white">{t('ready_book')}</h3><div className="flex justify-between text-sm text-gray-600 dark:text-gray-300"><span>{t('check_in')}</span><span>3:00 PM</span></div><div className="flex justify-between text-sm text-gray-600 dark:text-gray-300"><span>{t('check_out')}</span><span>11:00 AM</span></div><a href={acc.website} target="_blank" rel="noopener noreferrer" className="block w-full bg-blue-600 hover:bg-blue-700 text-white text-center py-3 rounded-xl font-bold transition-colors mt-4">{t('view_rooms')}</a></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

