import { GoogleGenAI } from "@google/genai";
import { ChatMessage, Source, GeneratedPlace } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAttractionSummary = async (attractionName: string, cityName: string, language: string = 'English'): Promise<string> => {
  try {
    const prompt = `Write a captivating, short (3 sentences) travel summary for ${attractionName} in ${cityName}. Focus on why a tourist must visit. Write the response in ${language} language.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No summary available.";
  } catch (error) {
    console.error("Gemini Summary Error:", error);
    return "AI is taking a break. Try again later!";
  }
};

export const generateCityGuide = async (city: string, country: string, language: string = 'English'): Promise<GeneratedPlace[]> => {
  try {
    const prompt = `You are a travel-data generator for my trip-planning app. For the city ${city}, ${country}, generate a structured list of the most important and popular places for travelers, including attractions, landmarks, viewpoints, museums, theme parks, famous streets, markets, beaches, and nearby day-trip spots. 

    CRITICAL: You must provide exact decimal LATITUDE and LONGITUDE for every single place so I can calculate driving distance.

    Do NOT copy or quote data from TripAdvisor or any other specific website; instead, use your own general knowledge to create original content. Return the result as clean JSON with an array called places, where each item has: name, category (attraction | museum | market | nature | beach | viewpoint | religious | historical | shopping | food-area | day-trip), short_description (max 40 words), approx_visit_time_hours, best_time_to_visit (morning/afternoon/evening), ideal_for (solo, couple, family, friends, senior), nearby_area (neighbourhood or area name), latitude (number), and longitude (number). Only include places that are genuinely useful for tourists, and keep the JSON valid.

    IMPORTANT: Write the 'name', 'short_description', 'nearby_area' and other text fields in ${language} language.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const jsonText = response.text || '{}';
    const json = JSON.parse(jsonText);

    // Map latitude/longitude to lat/lng if needed
    const mappedPlaces = (json.places || []).map((p: any) => ({
        ...p,
        lat: p.latitude || p.lat,
        lng: p.longitude || p.lng
    }));

    return mappedPlaces;
  } catch (error) {
    console.error("City Guide Generation Error:", error);
    return [];
  }
};

export const generateCountryDatabase = async (country: string, language: string = 'English'): Promise<GeneratedPlace[]> => {
  try {
    // Reduced count to 30 to prevent timeout/RPC errors on slower connections
    const prompt = `You are helping me build a travel database for my own app. For the country ${country} , generate top 30 different tourist places. Do NOT copy or quote TripAdvisor or any website; use your own knowledge.
Return CLEAN JSON with an array places.
Each place must have: id (short unique slug), name, category (attraction | museum | market | nature | beach | viewpoint | religious | historical | shopping | food-area | day-trip), short_description (max 40 words), approx_visit_time_hours, best_time_to_visit (morning/afternoon/evening), ideal_for (solo, couple, family, friends, senior), area_or_neighbourhood, latitude (number), longitude (number).
CRITICAL: You must provide exact decimal LATITUDE and LONGITUDE for every single place so I can map them.
Make sure all 30 places are unique and useful for tourists. Do not include duplicates or generic text. Output only valid JSON.
IMPORTANT: Write the 'name', 'short_description', 'area_or_neighbourhood' and other text fields in ${language} language.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
