export const getTravelChatResponse = async (
  history: ChatMessage[], 
  userMessage: string, 
  imageBase64?: string,
  location?: { lat: number, lng: number },
  language: string = 'English'
): Promise<{text: string, sources: Source[], relatedQuestions: string[]}> => {
  try {
    // Using Gemini 2.5 Flash for speed and efficient tool usage (Maps/Search)
    const chat = ai.chats.create({
      model: 'gemini-2.5-flash',
      history: history.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.text }] 
      })),
      config: {
        systemInstruction: `You are an advanced "Perplexity-style" travel research assistant. 
        1. ALWAYS use Google Search to find real-time info (prices, weather, events).
        2. ALWAYS use Google Maps to find precise locations, distances, and ratings when relevant.
        3. Be concise but comprehensive. Use Markdown for formatting.
        4. Provide your response in ${language}.
        5. At the very end of your response, strictly provide 3 brief, relevant follow-up questions in ${language} that the user might want to ask next.
        6. Format the follow-up questions exactly like this:

            ---RELATED---
            Question 1
            Question 2
            Question 3
        `,
        tools: [
          { googleSearch: {} }, 
          { googleMaps: {} }
        ],
        toolConfig: location ? {
            retrievalConfig: {
                latLng: {
                    latitude: location.lat,
                    longitude: location.lng
                }
            }
        } : undefined
      }
    });

    let messageContent;
    if (imageBase64) {
      // Construct multimodal message
      messageContent = [
        { text: userMessage },
        { 
          inlineData: { 
            mimeType: 'image/jpeg', 
            data: imageBase64.split(',')[1] // Remove data URL header if present
          } 
        }
      ];
    } else {
      messageContent = userMessage;
    }

    const response = await chat.sendMessage({ message: messageContent });

    // Extract Grounding Sources (Citations)
    const sources: Source[] = [];
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
      response.candidates[0].groundingMetadata.groundingChunks.forEach((chunk: any) => {
         // Web Sources
         if (chunk.web?.uri && chunk.web?.title) {
           sources.push({ title: chunk.web.title, uri: chunk.web.uri });
         }
         // Map Sources
         if (chunk.maps?.uri && chunk.maps?.title) {
           sources.push({ title: chunk.maps.title, uri: chunk.maps.uri });
         }
         // Fallback for some maps responses
         if (chunk.source?.uri && chunk.source?.title) {
            sources.push({ title: chunk.source.title, uri: chunk.source.uri });
         }
      });
    }

    // Parse Text and Related Questions
    let fullText = response.text || "I'm not sure how to answer that.";
    let relatedQuestions: string[] = [];
    const relatedSplit = fullText.split('---RELATED---');

    if (relatedSplit.length > 1) {
        fullText = relatedSplit[0].trim();
        const questionsRaw = relatedSplit[1].trim();
        relatedQuestions = questionsRaw.split('\n').filter(q => q.trim().length > 0).map(q => q.replace(/^- /, '').trim()).slice(0, 3);
    }

    return {
      text: fullText,
      sources: sources,
      relatedQuestions: relatedQuestions
    };
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return { text: "Sorry, I'm having trouble connecting to the travel servers.", sources: [], relatedQuestions: [] };
  }
};

// --- Routing Service (OSRM) ---
export const fetchRouteData = async (
  origin: { lat: number; lng: number },
  destination: { lat: number; lng: number }
): Promise<{ distanceText: string; durationText: string; distanceValue: number } | null> => {
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${origin.lng},${origin.lat};${destination.lng},${destination.lat}?overview=false`;
    const response = await fetch(url);
    if (!response.ok) return null;
    const data = await response.json();

    if (data.code === 'Ok' && data.routes?.[0]) {
      const route = data.routes[0];
      const distKmVal = route.distance / 1000;
      const distKm = distKmVal.toFixed(1);

      // Traffic Simulation Logic to match Google Maps style "Real-time Traffic"
      // OSRM provides 'optimistic' free-flow travel times.
      // We apply a dynamic multiplier based on distance to simulate urban density and traffic signals.

      let trafficMultiplier = 1.2; // Base padding

      if (distKmVal < 5) {
         // < 5km: High density city traffic, signals, small roads (avg speed ~15-20km/h)
         trafficMultiplier = 2.5; 
      } else if (distKmVal < 15) {
         // < 15km: Typical City commute (avg speed ~25-30km/h)
         trafficMultiplier = 2.0;
      } else if (distKmVal < 35) {
         // < 35km: Metro area / Suburban commute (avg speed ~40km/h)
         trafficMultiplier = 1.6;
      } else if (distKmVal < 80) {
         // < 80km: Highway/Intercity mix
         trafficMultiplier = 1.3;
      } else {
         // > 80km: Mostly highway cruising
         trafficMultiplier = 1.15;
      }

      const durMins = Math.round((route.duration / 60) * trafficMultiplier);

      let durText = `${durMins} min`;
      if (durMins >= 60) {
        const h = Math.floor(durMins / 60);
        const m = durMins % 60;
        durText = `${h} hr ${m} min`;
      }

      return {
        distanceText: `${distKm} km`,
        durationText: durText,
        distanceValue: route.distance
      };
    }
    return null;
  } catch (error) {
    // Silently fail for UI fallback
    return null;
  }
};

