                                                    className={`w-full p-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium ${tripInput.endDate ? 'text-slate-900 dark:text-white' : 'text-gray-400'}`} 
                                                    value={tripInput.endDate} 
                                                    onChange={(e) => setTripInput({...tripInput, endDate: e.target.value})} 
                                                />
                                            </div>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Details</label>
                                        <div className="flex gap-4">
                                            <div className="flex-1 relative"><Users className="absolute left-4 top-4 text-gray-400" size={18} /><select className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 dark:text-white appearance-none font-medium" value={tripInput.travelers} onChange={(e) => setTripInput({...tripInput, travelers: parseInt(e.target.value)})}>{[1,2,3,4,5,6].map(n => <option key={n} value={n}>{n} Traveler{n > 1 ? 's' : ''}</option>)}</select></div>
                                            <div className="flex-1 relative"><span className="absolute left-4 top-4 text-gray-400 font-bold text-lg flex items-center justify-center w-5 h-5 pointer-events-none">{currency.symbol}</span><input type="number" className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 dark:text-white font-medium" placeholder={`Budget`} value={tripInput.budget} onChange={(e) => setTripInput({...tripInput, budget: parseInt(e.target.value)})} /></div>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Trip Theme</label>
                                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                                        {['Relax', 'Adventure', 'Romantic', 'Family', 'Cultural'].map((theme) => (
                                            <button key={theme} onClick={() => setTripInput({...tripInput, theme: theme as TripTheme})} className={`p-5 rounded-xl border flex flex-col items-center justify-center gap-3 transition-all ${tripInput.theme === theme ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-500 text-indigo-700 dark:text-indigo-300 shadow-sm' : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-700 text-gray-500 hover:border-indigo-300'}`}>
                                                {theme === 'Relax' && <Palmtree size={28} />}
                                                {theme === 'Adventure' && <Compass size={28} />}
                                                {theme === 'Romantic' && <Heart size={28} />}
                                                {theme === 'Family' && <Users size={28} />}
                                                {theme === 'Cultural' && <Briefcase size={28} />}
                                                <span className="text-sm font-bold">{theme}</span>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <button onClick={handleGenerate} className="w-full py-5 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white rounded-2xl font-bold text-xl shadow-xl shadow-indigo-500/30 transition-all transform hover:scale-[1.01] flex items-center justify-center gap-3"><Sparkles className="animate-pulse" /> Generate My Plan</button>
                            </div>
                        )}
                        {step === 'loading' && (
                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white dark:bg-slate-950 z-30">
                                <div className="relative"><div className="w-24 h-24 border-4 border-indigo-100 dark:border-slate-800 rounded-full"></div><div className="absolute top-0 left-0 w-24 h-24 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div><Plane className="absolute inset-0 m-auto text-indigo-600 animate-pulse" size={32} /></div><h3 className="mt-8 text-xl font-bold text-slate-900 dark:text-white">Curating your experience...</h3><p className="text-gray-500 dark:text-gray-400 mt-2">Finding best flights and hidden gems.</p>
                            </div>
                        )}
                        {step === 'result' && tripResult && (
                            <div className="flex flex-col h-full">
                                <div className="bg-white dark:bg-slate-900 p-6 pb-0 shadow-sm z-10">
                                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
                                        <div><div className="flex items-center gap-2 mb-1"><h1 className="text-2xl font-black text-slate-900 dark:text-white">{tripResult.destination}</h1><span className="px-2 py-0.5 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300 rounded text-xs font-bold uppercase">{tripInput.theme} Trip</span></div><p className="text-sm text-gray-500">{tripResult.dates} • {tripResult.travelers} Travelers</p></div>
                                        <div className="text-right"><p className="text-xs text-gray-500 uppercase font-bold">Total Est. Cost</p><p className="text-2xl font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(tripResult.totalEstimatedCost, userProfile.currency)}</p></div>
                                    </div>
                                    <div className="flex gap-8 overflow-x-auto [&::-webkit-scrollbar]:hidden" style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}>{tabs.map((tab) => (<button key={tab} onClick={() => setActiveTab(tab)} className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap px-2 ${activeTab === tab ? 'border-indigo-600 text-indigo-600 dark:text-indigo-400' : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200'}`}>{tab}</button>))}</div>
                                </div>
                                <div className="flex-1 overflow-y-auto p-6 bg-slate-50 dark:bg-slate-900/50">
                                    {activeTab === 'Overview' && (
                                        <div className="max-w-4xl mx-auto space-y-6 animate-fade-in">
                                            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2"><Sparkles className="text-yellow-500" size={20} /> Trip Highlights</h3><ul className="grid grid-cols-1 md:grid-cols-3 gap-4">{tripResult.highlights.map((highlight, i) => (<li key={i} className="flex items-center gap-3 p-3 bg-yellow-50 dark:bg-yellow-900/10 rounded-xl border border-yellow-100 dark:border-yellow-900/30"><div className="w-2 h-2 rounded-full bg-yellow-500 shrink-0" /><span className="text-sm font-medium text-slate-700 dark:text-slate-200">{highlight}</span></li>))}</ul></div>
                                            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2"><Plane className="text-blue-500" size={20} /> Flight Summary</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-4">{['outbound', 'return'].map((type, i) => (<div key={i} className="bg-slate-50 dark:bg-slate-700/30 p-5 rounded-2xl border border-slate-100 dark:border-slate-600/50 relative overflow-hidden"><div className={`absolute top-0 right-0 w-16 h-16 ${i===0?'bg-blue-500/5':'bg-purple-500/5'} rounded-bl-full -mr-8 -mt-8`}></div><div className="flex justify-between items-start mb-4"><div className="flex items-center gap-3"><div className="w-10 h-10 bg-white rounded-full p-1 shadow-sm flex items-center justify-center overflow-hidden"><img src={tripResult.flights[type as keyof typeof tripResult.flights][0].logo} alt="Airline" className="w-full h-full object-contain" /></div><div><span className={`text-[10px] font-bold ${i===0?'text-blue-600 dark:text-blue-400 bg-blue-100 dark:bg-blue-900/30':'text-purple-600 dark:text-purple-400 bg-purple-100 dark:bg-purple-900/30'} uppercase tracking-wider px-1.5 py-0.5 rounded mb-1 inline-block`}>{type}</span><p className="font-bold text-sm text-slate-900 dark:text-white leading-tight">{tripResult.flights[type as keyof typeof tripResult.flights][0].airline}</p></div></div></div><div className="flex items-center justify-between text-center mb-4 relative"><div><p className="text-2xl font-black text-slate-900 dark:text-white mb-1">{tripResult.flights[type as keyof typeof tripResult.flights][0].origin}</p><p className="text-xs font-bold text-gray-500 mb-0.5">Boarding</p><p className="text-sm font-bold text-blue-600 dark:text-blue-400">{tripResult.flights[type as keyof typeof tripResult.flights][0].departureTime}</p></div><div className="flex-1 px-4 flex flex-col items-center"><div className="w-full h-[2px] bg-gray-300 dark:bg-slate-600 relative flex items-center justify-center rounded-full mt-2"><Plane size={14} className="text-gray-400 rotate-90 transform bg-slate-50 dark:bg-slate-800 p-0.5 rounded-full absolute z-10" /></div><p className="text-[10px] font-medium text-gray-400 mt-2 bg-white dark:bg-slate-800 px-2 rounded-full border border-gray-100 dark:border-slate-700">{tripResult.flights[type as keyof typeof tripResult.flights][0].duration}</p></div><div><p className="text-2xl font-black text-slate-900 dark:text-white mb-1">{tripResult.flights[type as keyof typeof tripResult.flights][0].destination}</p><p className="text-xs font-bold text-gray-500 mb-0.5">Dropping</p><p className="text-sm font-bold text-blue-600 dark:text-blue-400">{tripResult.flights[type as keyof typeof tripResult.flights][0].arrivalTime}</p></div></div></div>))}</div></div>
                                            <button onClick={handleSaveAndClose} className="w-full py-4 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-blue-500/30 transition-all flex items-center justify-center gap-2">{initialPlan ? 'Back to My Plans' : 'Confirm & Book Trip'} <ArrowRight size={20} /></button>
                                        </div>
                                    )}
                                    {activeTab === 'Itinerary' && (<div className="max-w-3xl mx-auto animate-fade-in"><h3 className="font-bold text-xl text-slate-900 dark:text-white mb-6 flex items-center gap-2"><Layout className="text-indigo-500" size={24} /> Daily Schedule</h3><div className="relative border-l-2 border-gray-200 dark:border-slate-700 ml-4 space-y-8">{tripResult.itinerary.map((day, i) => (<div key={i} className="relative pl-8"><div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-indigo-500 ring-4 ring-white dark:ring-slate-950"></div><div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-gray-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow"><div className="flex justify-between items-start mb-4"><div><h4 className="font-bold text-lg text-slate-900 dark:text-white">Day {day.day}: {day.title}</h4><p className="text-sm text-gray-500">{day.date}</p></div></div><div className="space-y-3">{day.activities.map((act, j) => (<div key={j} className="flex gap-4 p-3 rounded-xl bg-slate-50 dark:bg-slate-700/30"><div className="w-10 h-10 rounded-full bg-white dark:bg-slate-700 flex items-center justify-center shrink-0 shadow-sm text-gray-500">{act.icon === 'travel' && <Navigation size={18} className="text-blue-500" />}{act.icon === 'food' && <Utensils size={18} className="text-orange-500" />}{act.icon === 'activity' && <MapIcon size={18} className="text-emerald-500" />}</div><div><div className="flex items-center gap-2 mb-0.5"><span className="text-xs font-bold bg-gray-200 dark:bg-slate-600 px-1.5 py-0.5 rounded text-gray-700 dark:text-gray-300">{act.time}</span><h5 className="font-bold text-sm text-slate-800 dark:text-slate-200">{act.name}</h5></div><p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed">{act.description}</p></div></div>))}</div></div></div>))}</div></div>)}
                                    {activeTab === 'Accommodation' && (<div className="max-w-3xl mx-auto animate-fade-in"><div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-slate-900 dark:text-white mb-6 flex items-center gap-2"><Hotel className="text-orange-500" size={24} /> Selected Hotel</h3><div className="rounded-2xl overflow-hidden border border-gray-100 dark:border-slate-700 mb-6"><div className="h-64 w-full relative"><img src={tripResult.hotel.image} className="w-full h-full object-cover" alt="Hotel" /><div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-sm font-bold shadow-sm flex items-center gap-1 text-slate-800"><Heart size={14} className="text-red-500 fill-red-500" /> {tripResult.hotel.rating}</div></div><div className="p-6"><h4 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">{tripResult.hotel.name}</h4><p className="text-sm text-gray-500 mb-4 flex items-center gap-2"><MapPin size={16} /> {tripResult.hotel.address}</p><div className="mb-6"><h5 className="text-xs font-bold text-gray-500 uppercase mb-2">Amenities</h5><div className="flex flex-wrap gap-2">{tripResult.hotel.amenities.map(am => (<span key={am} className="text-xs bg-gray-100 dark:bg-slate-700 px-3 py-1.5 rounded-lg text-gray-700 dark:text-gray-300 border border-gray-200 dark:border-slate-600">{am}</span>))}</div></div><div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-slate-700"><div><p className="text-xs text-gray-400 uppercase font-bold">Price Per Night</p><p className="text-xl font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(tripResult.hotel.pricePerNight, userProfile.currency)}</p></div><a href={tripResult.hotel.website} target="_blank" rel="noopener noreferrer" onClick={(e) => e.stopPropagation()} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl text-sm font-bold transition-colors shadow-lg shadow-indigo-500/20">View Rooms & Book</a></div></div></div></div></div>)}
                                    {activeTab === 'Visa Requirements' && (<div className="max-w-3xl mx-auto animate-fade-in"><div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700"><h3 className="font-bold text-xl text-slate-900 dark:text-white mb-6 flex items-center gap-2"><ShieldCheck className="text-purple-500" size={24} /> Entry Requirements</h3><div className={`p-4 rounded-xl mb-6 flex items-center gap-4 ${tripResult.visa.required ? 'bg-orange-50 dark:bg-orange-900/20 border border-orange-100 dark:border-orange-800' : 'bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800'}`}><div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${tripResult.visa.required ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}>{tripResult.visa.required ? <Briefcase size={24} /> : <CheckCircle size={24} />}</div><div><p className={`font-bold ${tripResult.visa.required ? 'text-orange-800 dark:text-orange-200' : 'text-green-800 dark:text-green-200'}`}>{tripResult.visa.type}</p><p className="text-sm text-gray-600 dark:text-gray-400">{tripResult.visa.required ? 'Please allow sufficient time for processing.' : 'You can travel with your valid passport.'}</p></div></div><div className="space-y-6"><div><h4 className="font-bold text-sm text-gray-900 dark:text-white uppercase tracking-wide mb-3">Processing Time</h4><p className="text-gray-600 dark:text-gray-300 bg-gray-50 dark:bg-slate-700/50 p-3 rounded-lg inline-block border border-gray-200 dark:border-slate-600">{tripResult.visa.processingTime}</p></div>{tripResult.visa.required && (<div><h4 className="font-bold text-sm text-gray-900 dark:text-white uppercase tracking-wide mb-3">Documents Checklist</h4><ul className="grid grid-cols-1 md:grid-cols-2 gap-3">{tripResult.visa.checklist.map((item, idx) => (<li key={idx} className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-slate-700/30 rounded-xl border border-gray-100 dark:border-slate-600"><div className="w-5 h-5 rounded-full border-2 border-gray-300 dark:border-slate-500" /><span className="text-sm text-gray-700 dark:text-gray-300">{item}</span></li>))}</ul></div>)}</div><div className="mt-8 pt-6 border-t border-gray-100 dark:border-slate-700"><p className="text-xs text-gray-400 italic flex items-center gap-1"><ShieldCheck size={12} /> Information provided as a guide only. Verify with official embassies.</p></div></div></div>)}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* City Guide Section */}
            {activeSection === 'city' && (
                <div className="p-6 h-full">
                    <CityGuideSection onAddToWishlist={onAddToWishlist} onRemoveFromWishlist={onRemoveFromWishlist} itinerary={itinerary} language={userProfile.language} />
                </div>
            )}

            {/* Country Guide Section */}
            {activeSection === 'country' && (
                <div className="p-6 h-full">
                    <CountryGuideSection onAddToWishlist={onAddToWishlist} onRemoveFromWishlist={onRemoveFromWishlist} itinerary={itinerary} language={userProfile.language} />
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { TopNav, BottomNav } from './components/Navigation';
import { HomeView, SearchView, AttractionDetailView, ProfileView, AccommodationDetailView, RestaurantDetailView, MyPlansView, ImageWithFallback } from './components/TravelViews';
import { AIChat } from './components/AIChat';
import { EmergencyModal, EditModal, ProfileEditModal, AddActionModal, UserContributionModal } from './components/Modals';
import { SmartPlan } from './components/SmartPlan';
import { CityGuideModal } from './components/CityGuideModal';
import { CountryGuideModal } from './components/CountryGuideModal';
import { Attraction, UserProfile, Notification, DreamTripResult } from './types';
import { getTranslation } from './services/data';
import { ExternalLink, Trash2 } from 'lucide-react';

// Simple mock user state
const INITIAL_USER_PROFILE: UserProfile = {
  currency: 'USD',
  language: 'English',
  displayName: '',
  email: '',
  phone: '',
  country: '',
  age: '',
  gender: '',
  photoURL: ''
};

function App() {
  const [currentRoute, setCurrentRoute] = useState('home');
  const [routeParams, setRouteParams] = useState<any>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [itinerary, setItinerary] = useState<Attraction[]>([]);

  // Saved Plans State
  const [savedPlans, setSavedPlans] = useState<DreamTripResult[]>([]);
  const [selectedPlan, setSelectedPlan] = useState<DreamTripResult | null>(null);

  // User Profile State
  const [userProfile, setUserProfile] = useState<UserProfile>(INITIAL_USER_PROFILE);

  // Notifications State
  const [notifications, setNotifications] = useState<Notification[]>([
    { id: 1, title: 'Welcome to Go Pro', message: 'Start your journey by searching for a city!', time: 'Just now', unread: true },
    { id: 2, title: 'Flight Price Drop', message: 'Flights to Paris are down 15% this week.', time: '2h ago', unread: true },
    { id: 3, title: 'New Feature', message: 'Try our AI itinerary planner.', time: '1d ago', unread: false },
  ]);

  // Modals State
  const [isEmergencyOpen, setIsEmergencyOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isProfileEditOpen, setIsProfileEditOpen] = useState(false);
  const [isAddMenuOpen, setIsAddMenuOpen] = useState(false);
  const [contributionMode, setContributionMode] = useState<'add_place' | 'review' | 'photo' | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isSmartPlanOpen, setIsSmartPlanOpen] = useState(false);
  const [isCityGuideOpen, setIsCityGuideOpen] = useState(false);
  const [isCountryGuideOpen, setIsCountryGuideOpen] = useState(false);

  // Theme state
  const [darkMode, setDarkMode] = useState(false);

  // Effect to toggle dark mode on the html element
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const t = (key: string) => getTranslation(userProfile.language, key);

  // Navigate helper
  const navigate = (route: string, params: any = {}) => {
    window.scrollTo(0, 0);
    setCurrentRoute(route);
    setRouteParams(params);
  };

  const handleSearch = (q: string) => {
    setSearchQuery(q);
    navigate('search');
  };

  const addToItinerary = (items: Attraction | Attraction[]) => {
    setItinerary(prev => {
      const newItems = Array.isArray(items) ? items : [items];
      // Filter out duplicates
      const uniqueNewItems = newItems.filter(newItem => 
        !prev.some(existing => existing.id === newItem.id || existing.name === newItem.name)
      );
      return [...prev, ...uniqueNewItems];
    });
  };

  const removeFromItinerary = (id: string | string[]) => {
    setItinerary(prev => {
      if (Array.isArray(id)) {
        const idsToRemove = new Set(id);
        return prev.filter(i => !idsToRemove.has(i.id));
      }
      return prev.filter(i => i.id !== id);
    });
  };

  const updateProfile = (newProfile: UserProfile) => {
    setUserProfile(newProfile);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, unread: false })));
  };

  const handleSavePlan = (plan: DreamTripResult) => {
    // Avoid duplicates based on ID, update if exists
    setSavedPlans(prev => {
        const exists = prev.find(p => p.id === plan.id);
        if (exists) return prev.map(p => p.id === plan.id ? plan : p);
        return [...prev, plan];
    });
    // If it's a new plan being saved, navigate to my plans
    navigate('my-plans');
  };

  const handleViewPlan = (plan: DreamTripResult) => {
      setSelectedPlan(plan);
      setIsSmartPlanOpen(true);
  };

  const handleAddAction = (mode: 'add_place' | 'review' | 'photo' | 'city_guide' | 'country_db') => {
    // Close the add menu first
    setIsAddMenuOpen(false);

    if (mode === 'city_guide') {
      setContributionMode(null);
      setIsCountryGuideOpen(false);
      setIsCityGuideOpen(true);
    } else if (mode === 'country_db') {
      setContributionMode(null);
      setIsCityGuideOpen(false);
      setIsCountryGuideOpen(true);
    } else {
      setIsCityGuideOpen(false);
      setIsCountryGuideOpen(false);
      setContributionMode(mode as any);
    }
  };

  return (
    <div className="font-sans text-slate-800 bg-white dark:bg-slate-900 min-h-screen transition-colors duration-200">
      <TopNav 
        navigate={navigate} 
        currentRoute={currentRoute} 
        isLoggedIn={true} 
        openEmergency={() => setIsEmergencyOpen(true)}
        language={userProfile.language}
      />

      <main className="min-h-[calc(100vh-60px)] relative">
        {currentRoute === 'home' && (
          <HomeView 
            navigate={navigate} 
            handleSearch={handleSearch} 
            userProfile={userProfile} 
            notifications={notifications}
            markAllAsRead={markAllAsRead}
          />
        )}

        {currentRoute === 'search' && (
          <SearchView 
            navigate={navigate} 
            query={searchQuery} 
            setQuery={setSearchQuery} 
            userProfile={userProfile} 
          />
        )}

        {currentRoute === 'attraction' && (
          <AttractionDetailView 
            navigate={navigate} 
            id={routeParams.id} 
            addToItinerary={addToItinerary} 
            saved={itinerary.some(i => i.id === routeParams.id)}
            openEditModal={() => setIsEditModalOpen(true)}
            userProfile={userProfile}
            removeFromItinerary={removeFromItinerary}
          />
        )}

        {currentRoute === 'accommodation' && (
          <AccommodationDetailView 
            navigate={navigate} 
            id={routeParams.id}
            userProfile={userProfile}
          />
        )}

        {currentRoute === 'restaurant' && (
          <RestaurantDetailView 
            navigate={navigate} 
            id={routeParams.id}
            userProfile={userProfile}
          />
        )}

        {currentRoute === 'itinerary' && (
          <div className="max-w-4xl mx-auto px-4 py-4 pb-24 min-h-screen">
            <div className="flex items-center justify-between mb-3">
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t('wishlist_title')}</h1>
              {itinerary.length > 0 && (
