export const generateAttractionSummary = async (attractionName: string, cityName: string, language: string = 'English'): Promise<string> => {
  try {
    const prompt = `Write a captivating, short (3 sentences) travel summary for ${attractionName} in ${cityName}. Focus on why a tourist must visit. CRITICAL: Write the response entirely in ${language} language.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No summary available.";
  } catch (error) {
    console.error("Gemini Summary Error:", error);
    return "AI is taking a break. Try again later!";
  }
};

export const generateCityGuide = async (city: string, country: string, language: string = 'English'): Promise<GeneratedPlace[]> => {
  try {
    const prompt = `You are a travel-data generator for my trip-planning app. For the city ${city}, ${country}, generate a structured list of the most important and popular places for travelers.

    CRITICAL: You must provide exact decimal LATITUDE and LONGITUDE for every single place.
    Return the result as clean JSON with an array called places, where each item has: name, category, short_description (max 40 words), approx_visit_time_hours, best_time_to_visit, ideal_for, nearby_area, latitude, and longitude.

    IMPORTANT: All text fields (name, description, etc.) MUST be written in ${language} language.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const jsonText = response.text || '{}';
    const json = JSON.parse(jsonText);

    return (json.places || []).map((p: any) => ({
        ...p,
        lat: p.latitude || p.lat,
        lng: p.longitude || p.lng
    }));
  } catch (error) {
    console.error("City Guide Generation Error:", error);
    return [];
  }
};

