const MapPicker: React.FC<{ 
  label: string; 
  value: { name: string; lat: number; lng: number } | null;
  onChange: (val: { name: string; lat: number; lng: number }) => void;
}> = ({ label, value, onChange }) => {
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [tempLocation, setTempLocation] = useState<{ name: string; lat: number; lng: number } | null>(value);
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerInstanceRef = useRef<any>(null);

  useEffect(() => {
    if (isMapOpen && mapContainerRef.current && !mapInstanceRef.current) {
      const L = (window as any).L;
      if (!L) return;
      const startLat = value?.lat || 20;
      const startLng = value?.lng || 0;
      const startZoom = value ? 12 : 2;
      const map = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: true }).setView([startLat, startLng], startZoom);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Esri, Maxar', maxZoom: 19 }).addTo(map);
      L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}').addTo(map);
      if (value) markerInstanceRef.current = L.marker([value.lat, value.lng]).addTo(map);
      map.on('click', async (e: any) => {
        const { lat, lng } = e.latlng;
        if (markerInstanceRef.current) markerInstanceRef.current.remove();
        markerInstanceRef.current = L.marker([lat, lng]).addTo(map);
        setTempLocation({ name: 'Selected Location', lat, lng });
        try {
           const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
           const data = await res.json();
           const displayName = data.address?.city || data.address?.town || data.name || "Custom Location";
           setTempLocation({ name: displayName, lat, lng });
        } catch (err) { console.error(err); }
      });
      mapInstanceRef.current = map;
    }
    return () => { if (!isMapOpen && mapInstanceRef.current) { mapInstanceRef.current.remove(); mapInstanceRef.current = null; } };
  }, [isMapOpen]);

  useEffect(() => { if (isMapOpen) { setTempLocation(value); setSearchQuery(value?.name || ''); } }, [isMapOpen, value]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    try {
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}&limit=1`);
        const data = await response.json();
        if (data && data.length > 0) {
            const lat = parseFloat(data[0].lat);
            const lon = parseFloat(data[0].lon);
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([lat, lon], 13);
                if (markerInstanceRef.current) markerInstanceRef.current.remove();
                markerInstanceRef.current = L.marker([lat, lon]).addTo(mapInstanceRef.current);
            }
            setTempLocation({ name: data[0].display_name.split(',')[0], lat, lng: lon });
        }
    } catch (err) { console.error(err); } finally { setIsSearching(false); }
  };

  return (
    <>
      <div className="space-y-2"><label className="block text-xs font-bold text-gray-500 uppercase">{label}</label><button type="button" onClick={() => setIsMapOpen(true)} className={`w-full p-5 rounded-xl border text-left flex items-center justify-between transition-all hover:shadow-md ${value ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200' : 'bg-gray-50 dark:bg-slate-800 border-gray-200'}`}><div className="flex items-center gap-3"><div className={`p-2 rounded-full ${value ? 'bg-blue-500 text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400'}`}><MapPin size={18} /></div><div><p className={`font-bold text-sm ${value ? 'text-blue-900 dark:text-blue-100' : 'text-gray-500'}`}>{value ? value.name : 'Select Location'}</p></div></div><ArrowRight size={16} className="text-gray-400" /></button></div>
      {isMapOpen && createPortal(<div className="fixed inset-0 z-[100] bg-black/95 flex flex-col animate-fade-in"><div className="absolute top-4 left-4 right-4 z-[500] flex items-center gap-3"><button onClick={() => setIsMapOpen(false)} className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-xl"><ArrowLeft size={20} /></button><form onSubmit={handleSearch} className="flex-1 relative shadow-xl"><input value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search places..." className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 rounded-full outline-none" /><Search className="absolute left-4 top-3.5 text-gray-400" size={20} /></form></div><div className="w-full h-full relative"><div ref={mapContainerRef} className="w-full h-full" />{tempLocation && (<div className="absolute bottom-0 left-0 right-0 p-4 bg-white dark:bg-slate-900 rounded-t-3xl shadow-xl z-[500]"><div className="flex justify-between items-start mb-4 px-2"><div><h3 className="text-xl font-bold text-slate-900 dark:text-white mb-1">{tempLocation.name}</h3></div><div className="p-2 bg-blue-50 rounded-full"><MapPin className="text-blue-600" size={24} /></div></div><button onClick={() => { onChange(tempLocation); setIsMapOpen(false); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-xl font-bold text-lg">Set Location</button></div>)}</div></div>, document.body)}
