// Updated to gemini-2.5-flash for advanced reasoning and multimodal chat
export const getTravelChatResponse = async (
  history: ChatMessage[], 
  userMessage: string, 
  imageBase64?: string,
  location?: { lat: number, lng: number },
  language: string = 'English'
): Promise<{text: string, sources: Source[], relatedQuestions: string[]}> => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-2.5-flash',
      history: history.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.text }] 
      })),
      config: {
        systemInstruction: `You are an advanced travel assistant. 
        1. Respond strictly in ${language} language.
        2. Use Google Search and Maps where relevant.
        3. Provide 3 brief follow-up questions in ${language} at the end after '---RELATED---'.`,
        tools: [{ googleSearch: {} }, { googleMaps: {} }],
        toolConfig: location ? { retrievalConfig: { latLng: { latitude: location.lat, longitude: location.lng } } } : undefined
      }
    });

    const messageContent = imageBase64 ? [
      { text: userMessage },
      { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
    ] : userMessage;

    const response = await chat.sendMessage({ message: messageContent });

    const sources: Source[] = [];
    if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
      response.candidates[0].groundingMetadata.groundingChunks.forEach((chunk: any) => {
         if (chunk.web?.uri) sources.push({ title: chunk.web.title, uri: chunk.web.uri });
         if (chunk.maps?.uri) sources.push({ title: chunk.maps.title, uri: chunk.maps.uri });
      });
    }

    let fullText = response.text || "No response.";
    let relatedQuestions: string[] = [];
    const relatedSplit = fullText.split('---RELATED---');
    if (relatedSplit.length > 1) {
        fullText = relatedSplit[0].trim();
        relatedQuestions = relatedSplit[1].trim().split('\n').map(q => q.replace(/^- /, '').trim()).slice(0, 3);
    }

    return { text: fullText, sources, relatedQuestions };
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return { text: "Error connecting to AI.", sources: [], relatedQuestions: [] };
  }
};

export const fetchRouteData = async (
  origin: { lat: number; lng: number },
  destination: { lat: number; lng: number }
): Promise<{ distanceText: string; durationText: string; distanceValue: number } | null> => {
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${origin.lng},${origin.lat};${destination.lng},${destination.lat}?overview=false`;
    const response = await fetch(url);
    if (!response.ok) return null;
    const data = await response.json();
    if (data.code === 'Ok' && data.routes?.[0]) {
      const route = data.routes[0];
      const durMins = Math.round(route.duration / 60 * 1.5);
      const h = Math.floor(durMins / 60);
      const m = durMins % 60;
      return {
        distanceText: `${(route.distance / 1000).toFixed(1)} km`,
        durationText: h > 0 ? `${h} hr ${m} min` : `${m} min`,
        distanceValue: route.distance
      };
    }
    return null;
  } catch (error) { return null; }
};

