           <div className="grid grid-cols-3 gap-4 mt-8 max-w-md mx-auto">
               {[{ label: t('label_country'), value: userProfile.country || '-' }, { label: t('label_language'), value: userProfile.language }, { label: t('label_currency'), value: userProfile.currency }].map((stat, i) => (
                   <div key={i} className="text-center p-3 bg-gray-50 dark:bg-slate-700/50 rounded-2xl">
