import React, { useState, useEffect } from 'react';
import { X, Sparkles, MapPin, Globe, Loader2, Heart, Navigation, Clock, Sun, Users, Map, AlertCircle, ExternalLink, Star, Car } from 'lucide-react';
import { generateCityGuide, fetchRouteData } from '../services/geminiService';
import { GeneratedPlace, Attraction } from '../types';

interface CityGuideProps {
  onAddToWishlist: (attraction: Attraction | Attraction[]) => void;
  onRemoveFromWishlist: (id: string | string[]) => void;
  itinerary: Attraction[];
  language?: string;
}

interface CityGuideModalProps extends CityGuideProps {
  isOpen: boolean;
  onClose: () => void;
}

export const CityGuideSection: React.FC<CityGuideProps> = ({ onAddToWishlist, onRemoveFromWishlist, itinerary, language = 'English' }) => {
  const [city, setCity] = useState('');
  const [country, setCountry] = useState('');
  const [loading, setLoading] = useState(false);
  const [places, setPlaces] = useState<GeneratedPlace[]>([]);
  const [error, setError] = useState('');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);
  const [calculatingDistances, setCalculatingDistances] = useState(false);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        },
        (err) => {
          console.warn("Location permission denied", err);
        },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
  }, []);

  const processPlaces = async (rawPlaces: GeneratedPlace[]) => {
    if (!userLocation) return rawPlaces;
    setCalculatingDistances(true);

    const BATCH_SIZE = 5;
    const enhancedPlaces = [...rawPlaces];

    for (let i = 0; i < rawPlaces.length; i += BATCH_SIZE) {
        const batch = enhancedPlaces.slice(i, i + BATCH_SIZE);
        await Promise.all(batch.map(async (place, idx) => {
            if (place.lat && place.lng) {
                const realIdx = i + idx;
                const route = await fetchRouteData(userLocation, { lat: Number(place.lat), lng: Number(place.lng) });
                if (route) {
                    enhancedPlaces[realIdx] = {
                        ...place,
                        distance: route.distanceValue,
                        distanceText: route.distanceText,
                        travelTime: route.durationText + (route.durationText.includes('drive') || route.durationText.includes('min') ? ' drive' : '')
                    };
                }
            }
        }));
        await new Promise(r => setTimeout(r, 200));
    }

    enhancedPlaces.sort((a, b) => (a.distance || 999999999) - (b.distance || 999999999));

    setCalculatingDistances(false);
    return enhancedPlaces;
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!city || !country) return;

    setLoading(true);
    setError('');
    setPlaces([]);

    const results = await generateCityGuide(city, country, language);
    if (!results || results.length === 0) {
        setError('Could not generate guide. Please check the location and try again.');
        setPlaces([]);
        setLoading(false);
    } else {
        setPlaces(results);
        setLoading(false); 

        const sortedPlaces = await processPlaces(results);
        setPlaces(sortedPlaces);
    }
  };

  const getCategoryImage = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('museum') || cat.includes('history')) return 'https://images.unsplash.com/photo-1566127444979-b3d2b654e3d7?auto=format&fit=crop&w=400&q=80';
    if (cat.includes('nature') || cat.includes('park')) return 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=400&q=80';
    if (cat.includes('food') || cat.includes('market')) return 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=400&q=80';
    if (cat.includes('beach')) return 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=400&q=80';
    if (cat.includes('religious') || cat.includes('temple') || cat.includes('church')) return 'https://images.unsplash.com/photo-1548625361-bd8769f9d146?auto=format&fit=crop&w=400&q=80';
    return 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=400&q=80';
  };

  const handleToggleWishlist = (place: GeneratedPlace, index = 0) => {
    const existingItem = itinerary.find(i => i.name === place.name);

    if (existingItem) {
        onRemoveFromWishlist(existingItem.id);
    } else {
        const uniqueId = `gen_${Date.now()}_${index}_${Math.random().toString(36).substr(2, 9)}`;
        const attraction: Attraction = {
            id: uniqueId,
            cityId: `gen_${city.toLowerCase()}`,
            name: place.name,
            category: place.category,
            rating: 4.5, 
            price: 'Free',
            priceValue: 0,
            image: getCategoryImage(place.category),
            gallery: [],
            description: place.short_description,
            hours: '9:00 AM - 5:00 PM',
            address: `${place.nearby_area}, ${city}, ${country}`,
            website: ''
        };
        onAddToWishlist(attraction);
    }
  };

  const allAdded = places.length > 0 && places.every(place => itinerary.some(i => i.name === place.name));

  const handleToggleAll = () => {
    if (allAdded) {
        const idsToRemove = itinerary.filter(i => places.some(p => p.name === i.name)).map(i => i.id);
        onRemoveFromWishlist(idsToRemove);
    } else {
        const newAttractions: Attraction[] = [];
        places.forEach((place, index) => {
           if (!itinerary.some(i => i.name === place.name)) {
              const uniqueId = `gen_${Date.now()}_${index}_${Math.random().toString(36).substr(2, 9)}`;
              newAttractions.push({
                  id: uniqueId,
                  cityId: `gen_${city.toLowerCase()}`,
                  name: place.name,
                  category: place.category,
                  rating: 4.5,
                  price: 'Free',
                  priceValue: 0,
                  image: getCategoryImage(place.category),
                  gallery: [],
                  description: place.short_description,
                  hours: '9:00 AM - 5:00 PM',
                  address: `${place.nearby_area}, ${city}, ${country}`,
                  website: ''
              });
           }
        });
        if (newAttractions.length > 0) onAddToWishlist(newAttractions);
    }
  };

  const handleDirections = (place: GeneratedPlace) => {
      const destination = place.lat && place.lng 
        ? `${place.lat},${place.lng}` 
        : `${encodeURIComponent(place.name)},${encodeURIComponent(place.nearby_area)},${encodeURIComponent(city)},${encodeURIComponent(country)}`;

      let url = `https://www.google.com/maps/dir/?api=1&destination=${destination}&travelmode=driving`;
      if (userLocation) {
          url += `&origin=${userLocation.lat},${userLocation.lng}`;
      }
      window.open(url, '_blank');
  };

  const handleViewOnMap = () => {
    if (places.length > 0) {
        const routePlaces = places.slice(0, 20);
        const lastPlace = routePlaces[routePlaces.length - 1];

        const destParam = lastPlace.lat && lastPlace.lng 
            ? `${lastPlace.lat},${lastPlace.lng}`
            : `${encodeURIComponent(lastPlace.name)},${encodeURIComponent(lastPlace.nearby_area || city)}`;

        const waypointsParam = routePlaces.slice(0, routePlaces.length - 1).map(p => {
            return p.lat && p.lng 
                ? `${p.lat},${p.lng}`
                : `${encodeURIComponent(p.name)},${encodeURIComponent(p.nearby_area || city)}`;
        }).join('|');

        const originParam = userLocation 
            ? `${userLocation.lat},${userLocation.lng}`
            : 'My+Location';

        const url = `https://www.google.com/maps/dir/?api=1&origin=${originParam}&destination=${destParam}&waypoints=${waypointsParam}&travelmode=driving`;
        window.open(url, '_blank');
    }
  };

  return (
    <div className="flex flex-col h-full">
        <form onSubmit={handleGenerate} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-3 mb-4">
            <div className="relative">
                <MapPin className="absolute left-4 top-3.5 text-gray-400" size={18} />
                <input required value={city} onChange={(e) => setCity(e.target.value)} placeholder="City (e.g. London)" className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white font-medium" />
            </div>
            <div className="relative">
                <Globe className="absolute left-4 top-3.5 text-gray-400" size={18} />
                <input required value={country} onChange={(e) => setCountry(e.target.value)} placeholder="Country (e.g. UK)" className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white font-medium" />
            </div>
            <button type="submit" disabled={loading} className="px-8 py-3.5 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold shadow-lg shadow-purple-500/30 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed h-full">
                {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />} <span>Generate</span>
            </button>
        </form>

        {places.length > 0 && (
            <div className="flex gap-4 mb-6">
                <button onClick={handleToggleAll} className="flex-1 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl transition-colors border border-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/40">
                    {allAdded ? 'Remove All from Wishlist' : 'Add All to Wishlist'}
                </button>
                <button onClick={handleViewOnMap} className="flex-1 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl transition-colors border border-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/40">
                    View On Map
                </button>
            </div>
        )}

        {error && (
            <div className="mb-4 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl flex items-center gap-3 border border-red-100 dark:border-red-900/50">
                <AlertCircle size={20} /><p className="text-sm font-medium">{error}</p>
            </div>
        )}

        {loading ? (
            <div className="flex flex-col items-center justify-center py-20 space-y-4">
                <Loader2 className="w-12 h-12 text-purple-600 animate-spin" />
                <p className="text-gray-500 dark:text-gray-400 font-medium animate-pulse">Curating the best spots in {city}...</p>
            </div>
        ) : places.length > 0 ? (
            <div className="space-y-4">
                <div className="flex justify-between items-center">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white flex items-center gap-2"><Map size={20} className="text-purple-500" /> Top Places in {city}</h3>
                    <span className="text-sm text-gray-500 bg-white dark:bg-slate-800 px-3 py-1 rounded-full border border-gray-200 dark:border-slate-700">{places.length} results</span>
                </div>
                {calculatingDistances && (
                    <div className="text-xs text-emerald-600 dark:text-emerald-400 flex items-center gap-1.5 px-1 animate-pulse">
                        <Car size={14} /> Updating distances...
                    </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {places.map((place, idx) => {
                        const isAdded = itinerary.some(i => i.name === place.name);
                        return (
                            <div key={idx} onClick={() => handleDirections(place)} className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-all group cursor-pointer relative flex flex-col h-full">
                                <button onClick={(e) => { e.stopPropagation(); handleToggleWishlist(place, idx); }} className={`absolute top-4 right-4 p-2 rounded-full transition-colors z-10 ${isAdded ? 'bg-pink-50 text-pink-600' : 'bg-gray-50 dark:bg-slate-700 text-gray-400 hover:bg-pink-50 hover:text-pink-600'}`}>
                                    <Heart size={20} className={isAdded ? "fill-current" : ""} />
                                </button>
                                <div className="mb-2 pr-10">
                                    <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                                        <span className="px-2 py-0.5 bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-300 rounded text-[10px] font-bold uppercase tracking-wider">{place.category}</span>
                                        <span className="px-2 py-0.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-300 rounded text-[10px] font-bold uppercase tracking-wider flex items-center gap-1"><Clock size={10} /> {place.best_time_to_visit}</span>
                                    </div>
                                    <h4 className="font-bold text-lg text-slate-900 dark:text-white leading-tight">{place.name}</h4>
                                    <div className="flex items-center gap-1 mt-1 text-yellow-500">
                                        <span className="text-xs font-bold text-slate-700 dark:text-slate-300">4.5</span>
                                        <div className="flex"><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor" className="text-gray-300"/></div>
                                        <span className="text-[10px] text-gray-400">(Google Review)</span>
                                    </div>
                                </div>
                                <p className="text-sm text-gray-600 dark:text-gray-300 mb-4 line-clamp-2">{place.short_description}</p>
                                <div className="mt-auto">
                                    <div className="flex items-center gap-2 mb-3">
                                        <div className="flex items-center gap-2 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-900/10 rounded-lg border border-emerald-100 dark:border-emerald-900/30 w-full md:w-auto">
                                            <Navigation size={16} className="text-emerald-600 dark:text-emerald-400" />
                                            {place.distanceText ? (
                                                <span className="text-sm font-bold text-emerald-700 dark:text-emerald-400 truncate">{place.distanceText} • {place.travelTime}</span>
                                            ) : (
                                                <span className="text-xs font-medium text-gray-400 italic">
                                                    {calculatingDistances ? 'Calculating...' : 'Distance unavailable'}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap gap-3 pt-3 border-t border-gray-50 dark:border-slate-700/50">
                                        <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400"><MapPin size={12} /> {place.nearby_area}</div>
                                        <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400"><Users size={12} /> {place.ideal_for}</div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center py-20 opacity-50 h-full"><Globe className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" /><p className="text-gray-500 dark:text-gray-400">Enter a city and country name to generate guide</p></div>
        )}
    </div>
  );
};

