                <button onClick={handleToggleAll} className="flex-1 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl transition-colors border border-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/40">
                   {allAdded ? 'Remove All from Wishlist' : 'Add All to Wishlist'}
