export const ImageWithFallback: React.FC<{ src: string, alt: string, className?: string }> = ({ src, alt, className }) => {
  const [error, setError] = useState(false);

  useEffect(() => {
    setError(false);
  }, [src]);

  if (error) {
    return (
      <div className={`flex items-center justify-center bg-gray-200 dark:bg-slate-700 text-gray-400 dark:text-gray-500 ${className}`}>
        <div className="text-center p-2 overflow-hidden">
           <MapPin size={24} className="mx-auto mb-1 opacity-50" />
           <span className="text-[10px] font-medium leading-tight block truncate w-full">{alt}</span>
        </div>
      </div>
    );
  }

  return (
    <img 
      src={src} 
      alt={alt} 
      className={className}
      onError={() => setError(true)}
      loading="lazy"
      crossOrigin="anonymous"
    />
  );
};

export const HomeView: React.FC<HomeViewProps> = ({ navigate, handleSearch, userProfile, notifications, markAllAsRead }) => {
  const [isListening, setIsListening] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  const t = (key: string) => getTranslation(userProfile.language, key);

  const unreadCount = notifications.filter(n => n.unread).length;

  const handleVoiceSearch = () => {
    if ('webkitSpeechRecognition' in window) {
        const recognition = new (window as any).webkitSpeechRecognition();
        recognition.lang = 'en-US';
        recognition.onstart = () => setIsListening(true);
        recognition.onend = () => setIsListening(false);
        recognition.onerror = (event: any) => {
             setIsListening(false);
             if (event.error === 'not-allowed' || event.error === 'permission-denied') {
                 setShowSettings(true);
             }
        };
        recognition.onresult = (event: any) => {
            const transcript = event.results[0][0].transcript;
            handleSearch(transcript);
        };
        recognition.start();
    } else {
        alert("Voice search is not supported in this browser.");
    }
  };

  return (
    <div className="pb-20 md:pb-0 bg-white dark:bg-slate-900">
       <div className="relative w-full">
         <div className="absolute inset-0 h-full">
            <ImageWithFallback src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=1200&q=80" className="w-full h-full object-cover" alt="Hero Background" />
            <div className="absolute inset-0 bg-black/40" />
         </div>

         <div className="relative z-10 flex flex-col items-center justify-center px-4 text-center pt-4 pb-4">

           <div className="flex items-center gap-2 w-full max-w-xl justify-center mb-3 relative z-20">
             <div className="flex-1 bg-white dark:bg-slate-800 p-1 rounded-full shadow-xl flex items-center min-w-0 h-12">
               <MapPin className="ml-3 text-gray-400 shrink-0" size={18} />
               <input 
                 type="text" 
                 placeholder={t('search_placeholder')} 
                 className="flex-1 px-2 py-2 outline-none text-gray-700 dark:text-gray-200 bg-transparent min-w-0 text-sm md:text-base truncate" 
                 onKeyDown={(e) => e.key === 'Enter' && handleSearch(e.currentTarget.value)} 
               />
               <button onClick={handleVoiceSearch} className={`p-2 mr-1 shrink-0 rounded-full transition-colors ${isListening ? 'bg-red-100 text-red-600' : 'hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-500'}`}>
                   <Mic size={18} />
               </button>
               <button 
                onClick={() => handleSearch((document.querySelector('input[type="text"]') as HTMLInputElement).value)} 
                className="bg-blue-700 hover:bg-blue-800 text-white px-4 py-1.5 rounded-full font-medium transition-colors shrink-0 whitespace-nowrap text-sm md:text-base h-10"
               >
                {t('search_btn')}
               </button>
             </div>

             <div className="relative shrink-0">
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="bg-blue-600 hover:bg-blue-700 text-white p-0 rounded-full shadow-lg transition-transform hover:scale-105 active:scale-95 flex items-center justify-center h-12 w-12"
                >
                  <Bell size={20} />
                  {unreadCount > 0 && (
                    <span className="absolute top-2.5 right-3 flex h-2.5 w-2.5">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-red-500 border border-white"></span>
                    </span>
                  )}
                </button>

                 {showNotifications && (
                    <div className="absolute top-full right-0 mt-3 z-50 w-80 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border border-gray-100 dark:border-slate-700 overflow-hidden animate-fade-in-up origin-top-right">
                        <div className="p-4 border-b border-gray-100 dark:border-slate-800 flex justify-between items-center bg-gray-50 dark:bg-slate-800/50">
                            <h3 className="font-bold text-gray-900 dark:text-white">{t('notifications')} {unreadCount > 0 && `(${unreadCount})`}</h3>
                            <button onClick={() => setShowNotifications(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X size={18} /></button>
                        </div>
                        <div className="max-h-80 overflow-y-auto">
                            {notifications.length === 0 ? (
                                <div className="p-8 text-center text-gray-400 text-sm">{t('no_notifications')}</div>
                            ) : (
                                notifications.map(n => (
                                    <div key={n.id} className={`p-4 border-b border-gray-50 dark:border-slate-800 hover:bg-gray-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer ${n.unread ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}>
                                        <div className="flex justify-between items-start mb-1">
                                            <h4 className={`text-sm font-bold ${n.unread ? 'text-blue-600 dark:text-blue-400' : 'text-gray-900 dark:text-white'}`}>{n.title}</h4>
                                            <span className="text-[10px] text-gray-400">{n.time}</span>
                                        </div>
                                        <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed">{n.message}</p>
