                        <div className="p-2 bg-gray-50 dark:bg-slate-800 text-center border-t border-gray-100 dark:border-slate-800">
                            <button onClick={markAllAsRead} className="text-xs font-bold text-blue-600 hover:text-blue-700 py-2 disabled:opacity-50 disabled:cursor-not-allowed" disabled={unreadCount === 0}>{t('mark_read')}</button>
