         <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-4">
           {MOCK_DB.cities.slice(0,4).map(city => (
             <div key={city.id} onClick={() => handleSearch(city.name)} className="group cursor-pointer flex flex-col gap-2">
