                 <p className="text-xs md:text-sm text-gray-500 dark:text-gray-400 truncate">{city.country}</p>
               </div>
             </div>
           ))}
         </div>
       </div>
       <SettingsModal isOpen={showSettings} onClose={() => setShowSettings(false)} type="privacy" />
    </div>
  );
