import React, { useState, useEffect } from 'react';
import { TopNav, BottomNav } from './components/Navigation';
import { HomeView, SearchView, AttractionDetailView, ProfileView, AccommodationDetailView, RestaurantDetailView, MyPlansView, ImageWithFallback } from './components/TravelViews';
import { AIChat } from './components/AIChat';
import { EmergencyModal, EditModal, ProfileEditModal, AddActionModal, UserContributionModal } from './components/Modals';
import { SmartPlan } from './components/SmartPlan';
import { CityGuideModal } from './components/CityGuideModal';
import { CountryGuideModal } from './components/CountryGuideModal';
import { Attraction, UserProfile, Notification, DreamTripResult } from './types';
import { getTranslation } from './services/data';
import { ExternalLink, Trash2 } from 'lucide-react';

// Simple mock user state
const INITIAL_USER_PROFILE: UserProfile = {
  currency: 'USD',
  language: 'English',
  displayName: '',
  email: '',
  phone: '',
  country: '',
  age: '',
  gender: '',
  photoURL: ''
};

function App() {
  const [currentRoute, setCurrentRoute] = useState('home');
  const [routeParams, setRouteParams] = useState<any>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [itinerary, setItinerary] = useState<Attraction[]>([]);

  // Saved Plans State
  const [savedPlans, setSavedPlans] = useState<DreamTripResult[]>([]);
  const [selectedPlan, setSelectedPlan] = useState<DreamTripResult | null>(null);

  // User Profile State
  const [userProfile, setUserProfile] = useState<UserProfile>(INITIAL_USER_PROFILE);

  // Notifications State
  const [notifications, setNotifications] = useState<Notification[]>([
    { id: 1, title: 'Welcome to Go Pro', message: 'Start your journey by searching for a city!', time: 'Just now', unread: true },
    { id: 2, title: 'Flight Price Drop', message: 'Flights to Paris are down 15% this week.', time: '2h ago', unread: true },
    { id: 3, title: 'New Feature', message: 'Try our AI itinerary planner.', time: '1d ago', unread: false },
  ]);

  // Modals State
  const [isEmergencyOpen, setIsEmergencyOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isProfileEditOpen, setIsProfileEditOpen] = useState(false);
  const [isAddMenuOpen, setIsAddMenuOpen] = useState(false);
  const [contributionMode, setContributionMode] = useState<'add_place' | 'review' | 'photo' | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isSmartPlanOpen, setIsSmartPlanOpen] = useState(false);
  const [isCityGuideOpen, setIsCityGuideOpen] = useState(false);
  const [isCountryGuideOpen, setIsCountryGuideOpen] = useState(false);

  // Theme state
  const [darkMode, setDarkMode] = useState(false);

  // Effect to toggle dark mode on the html element
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const t = (key: string) => getTranslation(userProfile.language, key);

  // Navigate helper
  const navigate = (route: string, params: any = {}) => {
    window.scrollTo(0, 0);
    setCurrentRoute(route);
    setRouteParams(params);
  };

  const handleSearch = (q: string) => {
    setSearchQuery(q);
    navigate('search');
  };

  const addToItinerary = (items: Attraction | Attraction[]) => {
    setItinerary(prev => {
      const newItems = Array.isArray(items) ? items : [items];
      // Filter out duplicates
      const uniqueNewItems = newItems.filter(newItem => 
        !prev.some(existing => existing.id === newItem.id || existing.name === newItem.name)
      );
      return [...prev, ...uniqueNewItems];
    });
  };

  const removeFromItinerary = (id: string | string[]) => {
    setItinerary(prev => {
      if (Array.isArray(id)) {
        const idsToRemove = new Set(id);
        return prev.filter(i => !idsToRemove.has(i.id));
      }
      return prev.filter(i => i.id !== id);
    });
  };

  const updateProfile = (newProfile: UserProfile) => {
    setUserProfile(newProfile);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, unread: false })));
  };

  const handleSavePlan = (plan: DreamTripResult) => {
    // Avoid duplicates based on ID, update if exists
    setSavedPlans(prev => {
        const exists = prev.find(p => p.id === plan.id);
        if (exists) return prev.map(p => p.id === plan.id ? plan : p);
        return [...prev, plan];
    });
    // If it's a new plan being saved, navigate to my plans
    navigate('my-plans');
  };

  const handleViewPlan = (plan: DreamTripResult) => {
      setSelectedPlan(plan);
      setIsSmartPlanOpen(true);
  };

  const handleAddAction = (mode: 'add_place' | 'review' | 'photo' | 'city_guide' | 'country_db') => {
    // Close the add menu first
    setIsAddMenuOpen(false);

    if (mode === 'city_guide') {
      setContributionMode(null);
      setIsCountryGuideOpen(false);
      setIsCityGuideOpen(true);
    } else if (mode === 'country_db') {
      setContributionMode(null);
      setIsCityGuideOpen(false);
      setIsCountryGuideOpen(true);
    } else {
      setIsCityGuideOpen(false);
      setIsCountryGuideOpen(false);
      setContributionMode(mode as any);
    }
  };

  return (
    <div className="font-sans text-slate-800 bg-white dark:bg-slate-900 min-h-screen transition-colors duration-200">
      <TopNav 
        navigate={navigate} 
        currentRoute={currentRoute} 
        isLoggedIn={true} 
        openEmergency={() => setIsEmergencyOpen(true)}
        language={userProfile.language}
      />

      <main className="min-h-[calc(100vh-60px)] relative">
        {currentRoute === 'home' && (
          <HomeView 
            navigate={navigate} 
            handleSearch={handleSearch} 
            userProfile={userProfile} 
            notifications={notifications}
            markAllAsRead={markAllAsRead}
          />
        )}

        {currentRoute === 'search' && (
          <SearchView 
            navigate={navigate} 
            query={searchQuery} 
            setQuery={setSearchQuery} 
            userProfile={userProfile} 
            handleSearch={handleSearch}
          />
        )}

        {currentRoute === 'attraction' && (
          <AttractionDetailView 
            navigate={navigate} 
            id={routeParams.id} 
            addToItinerary={addToItinerary} 
            saved={itinerary.some(i => i.id === routeParams.id)}
            openEditModal={() => setIsEditModalOpen(true)}
            userProfile={userProfile}
            removeFromItinerary={removeFromItinerary}
          />
        )}

        {currentRoute === 'accommodation' && (
          <AccommodationDetailView 
            navigate={navigate} 
            id={routeParams.id}
            userProfile={userProfile}
          />
        )}

        {currentRoute === 'restaurant' && (
          <RestaurantDetailView 
            navigate={navigate} 
            id={routeParams.id}
            userProfile={userProfile}
          />
        )}

        {currentRoute === 'itinerary' && (
          <div className="max-w-4xl mx-auto px-4 py-4 pb-24 min-h-screen">
            <div className="flex items-center justify-between mb-3">
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{t('wishlist_title')}</h1>
              {itinerary.length > 0 && (
                <span className="text-sm font-medium bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-3 py-1 rounded-full">
                  {itinerary.length} items
                </span>
              )}
            </div>

            {itinerary.length === 0 ? (
              <div className="text-center py-20 bg-gray-50 dark:bg-slate-800 rounded-3xl border border-dashed border-gray-200 dark:border-slate-700">
                 <div className="text-gray-400 mb-2">No items saved yet</div>
                 <div className="text-sm text-gray-500">{t('wishlist_empty')}</div>
              </div>
            ) : (
              <div className="space-y-3">
                {itinerary.map(item => (
                  <div 
                    key={item.id} 
                    onClick={() => window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.name + ' ' + (item.address || ''))}`, '_blank')}
                    className="flex bg-white dark:bg-slate-800 p-3 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 gap-3 transition-all hover:shadow-md cursor-pointer group"
                  >
                    <div className="w-24 h-24 shrink-0 rounded-lg overflow-hidden bg-gray-100 dark:bg-slate-700">
                        <ImageWithFallback src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                    </div>
                    <div className="flex-1 flex flex-col justify-between">
                      <div>
                        <div className="flex justify-between items-start">
                           <h3 className="font-bold text-gray-900 dark:text-white text-lg leading-tight group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{item.name}</h3>
                           <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               removeFromItinerary(item.id);
                             }} 
                             className="text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 p-1.5 rounded-full transition-colors z-10 relative"
                             title="Remove"
                           >
                              <Trash2 size={18} />
                           </button>
                        </div>
                        <p className="text-sm text-blue-600 dark:text-blue-400 font-medium mb-1">{item.category}</p>
                        <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-1">{item.address}</p>
                      </div>
                      <div className="flex justify-end pt-2 items-center gap-4">
                        {item.website && (
                             <a 
                               href={item.website} 
                               target="_blank" 
                               rel="noopener noreferrer" 
                               onClick={(e) => e.stopPropagation()}
                               className="text-xs font-bold text-gray-500 hover:text-blue-600 z-10 relative"
                             >
                               Website
                             </a>
                        )}
                        <span className="text-xs font-bold text-blue-600 group-hover:text-blue-700 flex items-center gap-1">
                            View on Map <ExternalLink size={12} />
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {currentRoute === 'my-plans' && (
            <MyPlansView 
                navigate={navigate} 
                userProfile={userProfile} 
                plans={savedPlans}
                onViewPlan={handleViewPlan}
            />
        )}

        {currentRoute === 'profile' && (
            <ProfileView 
              navigate={navigate} 
              userProfile={userProfile} 
              openEditModal={() => setIsProfileEditOpen(true)}
              toggleTheme={() => setDarkMode(!darkMode)}
              darkMode={darkMode}
            />
        )}
      </main>

      <BottomNav 
        navigate={navigate} 
        currentRoute={currentRoute} 
        openEmergency={() => setIsEmergencyOpen(true)} 
        openAddMenu={() => setIsAddMenuOpen(true)}
        language={userProfile.language} 
      />

      <AIChat 
        isOpen={isChatOpen} 
        setIsOpen={setIsChatOpen} 
        onOpenSmartPlan={() => {
            setSelectedPlan(null); // Ensure we start fresh
            setIsSmartPlanOpen(true);
        }}
      />

      <EmergencyModal isOpen={isEmergencyOpen} onClose={() => setIsEmergencyOpen(false)} country={userProfile.country} />
      <EditModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={handleSavePlan} />
      <AddActionModal 
        isOpen={isAddMenuOpen} 
        onClose={() => setIsAddMenuOpen(false)} 
        onAction={handleAddAction}
      />
      <UserContributionModal 
        isOpen={contributionMode !== null}
        onClose={() => setContributionMode(null)}
        mode={contributionMode}
      />
      <ProfileEditModal 
        isOpen={isProfileEditOpen} 
        onClose={() => setIsProfileEditOpen(false)} 
        profile={userProfile} 
        onSave={updateProfile}
      />
      <SmartPlan 
        isOpen={isSmartPlanOpen} 
        onClose={() => setIsSmartPlanOpen(false)} 
        userProfile={userProfile}
        onSave={handleSavePlan}
        initialPlan={selectedPlan}
        onAddToWishlist={addToItinerary}
        onRemoveFromWishlist={removeFromItinerary}
        itinerary={itinerary}
      />
      <CityGuideModal 
        isOpen={isCityGuideOpen}
        onClose={() => setIsCityGuideOpen(false)}
        onAddToWishlist={addToItinerary}
        onRemoveFromWishlist={removeFromItinerary}
        itinerary={itinerary}
      />
      <CountryGuideModal 
        isOpen={isCountryGuideOpen}
        onClose={() => setIsCountryGuideOpen(false)}
        onAddToWishlist={addToItinerary}
        onRemoveFromWishlist={removeFromItinerary}
        itinerary={itinerary}
      />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { X, Sparkles, Globe, Loader2, Heart, Navigation, Clock, Sun, Users, Database, FileJson, AlertCircle, ExternalLink, Star, Car, MapPin, Map } from 'lucide-react';
import { generateCountryDatabase, fetchRouteData } from '../services/geminiService';
import { GeneratedPlace, Attraction } from '../types';

interface CountryGuideProps {
  onAddToWishlist: (attraction: Attraction | Attraction[]) => void;
  onRemoveFromWishlist: (id: string | string[]) => void;
  itinerary: Attraction[];
  language?: string;
}

interface CountryGuideModalProps extends CountryGuideProps {
  isOpen: boolean;
  onClose: () => void;
}

export const CountryGuideSection: React.FC<CountryGuideProps> = ({ onAddToWishlist, onRemoveFromWishlist, itinerary, language = 'English' }) => {
  const [country, setCountry] = useState('');
  const [loading, setLoading] = useState(false);
  const [places, setPlaces] = useState<GeneratedPlace[]>([]);
  const [error, setError] = useState('');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);
  const [calculatingDistances, setCalculatingDistances] = useState(false);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => { setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }); },
        (err) => { console.warn("Location permission denied", err); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
  }, []);

  const processPlaces = async (rawPlaces: GeneratedPlace[]) => {
    if (!userLocation) return rawPlaces;
    setCalculatingDistances(true);

    // Process in batches
    const BATCH_SIZE = 5;
    const enhancedPlaces = [...rawPlaces];

    for (let i = 0; i < rawPlaces.length; i += BATCH_SIZE) {
        const batch = enhancedPlaces.slice(i, i + BATCH_SIZE);
        await Promise.all(batch.map(async (place, idx) => {
            if (place.lat && place.lng) {
                const realIdx = i + idx;
                const route = await fetchRouteData(userLocation, { lat: Number(place.lat), lng: Number(place.lng) });
                if (route) {
                    enhancedPlaces[realIdx] = {
                        ...place,
                        distance: route.distanceValue,
                        distanceText: route.distanceText,
                        travelTime: route.durationText + (route.durationText.includes('drive') || route.durationText.includes('min') ? ' drive' : '')
                    };
                }
            }
        }));
        await new Promise(r => setTimeout(r, 200));
    }

    enhancedPlaces.sort((a, b) => (a.distance || 999999999) - (b.distance || 999999999));
    setCalculatingDistances(false);
    return enhancedPlaces;
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!country) return;

    setLoading(true);
    setError('');
    setPlaces([]);

    const results = await generateCountryDatabase(country, language);
    if (!results || results.length === 0) {
        setError('Could not generate plan. Please check the country name and try again.');
        setLoading(false);
    } else {
        setPlaces(results);
        setLoading(false);
        const sortedPlaces = await processPlaces(results);
        setPlaces(sortedPlaces);
    }
  };

  const createAttractionFromPlace = (place: GeneratedPlace, index: number): Attraction => {
    const uniqueId = `gen_${Date.now()}_${index}_${Math.random().toString(36).substr(2, 9)}`;
    return {
        id: uniqueId,
        cityId: `gen_${country.toLowerCase()}_db`,
        name: place.name,
        category: place.category,
        rating: 4.5,
        price: 'N/A',
        priceValue: 0,
        image: 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=400&q=80',
        gallery: [],
        description: place.short_description,
        hours: 'Variable',
        address: `${place.nearby_area}, ${country}`,
        website: ''
    };
  };

  const handleToggleWishlist = (place: GeneratedPlace, index = 0) => {
    const existingItem = itinerary.find(i => i.name === place.name);
    if (existingItem) {
        onRemoveFromWishlist(existingItem.id);
    } else {
        onAddToWishlist(createAttractionFromPlace(place, index));
    }
  };

  const allAdded = places.length > 0 && places.every(place => itinerary.some(i => i.name === place.name));

  const handleToggleAll = () => {
    if (allAdded) {
        const idsToRemove = itinerary.filter(i => places.some(p => p.name === i.name)).map(i => i.id);
        onRemoveFromWishlist(idsToRemove);
    } else {
        const newAttractions: Attraction[] = [];
        places.forEach((place, index) => {
           if (!itinerary.some(i => i.name === place.name)) {
              newAttractions.push(createAttractionFromPlace(place, index));
           }
        });
        if (newAttractions.length > 0) onAddToWishlist(newAttractions);
    }
  };

  const handleDirections = (place: GeneratedPlace) => {
      const destination = place.lat && place.lng 
        ? `${place.lat},${place.lng}` 
        : `${encodeURIComponent(place.name)},${encodeURIComponent(place.nearby_area)},${encodeURIComponent(country)}`;
      let url = `https://www.google.com/maps/dir/?api=1&destination=${destination}&travelmode=driving`;
      if (userLocation) {
          url += `&origin=${userLocation.lat},${userLocation.lng}`;
      }
      window.open(url, '_blank');
  };

  const handleViewOnMap = () => {
    if (places.length > 0) {
        const routePlaces = places.slice(0, 20); // Limit to avoid URL overflow
        const lastPlace = routePlaces[routePlaces.length - 1];

        const destParam = lastPlace.lat && lastPlace.lng 
            ? `${lastPlace.lat},${lastPlace.lng}`
            : `${encodeURIComponent(lastPlace.name)},${encodeURIComponent(lastPlace.nearby_area || country)}`;

        const waypointsParam = routePlaces.slice(0, routePlaces.length - 1).map(p => {
            return p.lat && p.lng 
                ? `${p.lat},${p.lng}`
                : `${encodeURIComponent(p.name)},${encodeURIComponent(p.nearby_area || country)}`;
        }).join('|');

        const originParam = userLocation 
            ? `${userLocation.lat},${userLocation.lng}`
            : 'My+Location';

        const url = `https://www.google.com/maps/dir/?api=1&origin=${originParam}&destination=${destParam}&waypoints=${waypointsParam}&travelmode=driving`;
        window.open(url, '_blank');
    }
  };

  return (
    <div className="flex flex-col h-full">
        <form onSubmit={handleGenerate} className="grid grid-cols-1 md:grid-cols-[1fr_auto] gap-3 mb-4">
            <div className="relative">
                <Globe className="absolute left-4 top-3.5 text-gray-400" size={18} />
                <input required value={country} onChange={(e) => setCountry(e.target.value)} placeholder="Enter Country (e.g. India)" className="w-full pl-12 pr-4 py-3.5 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white font-medium" />
            </div>
            <button type="submit" disabled={loading} className="px-8 py-3.5 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold shadow-lg shadow-purple-500/30 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed">
              {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={18} />} <span>Generate Plan</span>
            </button>
        </form>

        {places.length > 0 && (
            <div className="flex gap-4 mb-6">
                <button onClick={handleToggleAll} className="flex-1 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl transition-colors border border-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/40">
                   {allAdded ? 'Remove All from Wishlist' : 'Add All to Wishlist'}
                </button>
                <button onClick={handleViewOnMap} className="flex-1 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl transition-colors border border-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/40">
                    View On Map
                </button>
            </div>
        )}

        {error && (
            <div className="mb-4 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl flex items-center gap-3 border border-red-100 dark:border-red-900/50">
                <AlertCircle size={20} /><p className="text-sm font-medium">{error}</p>
            </div>
        )}

        {loading ? (
            <div className="flex flex-col items-center justify-center py-20 space-y-4">
                <div className="relative"><div className="w-16 h-16 border-4 border-purple-100 dark:border-purple-900/30 rounded-full"></div><div className="absolute top-0 left-0 w-16 h-16 border-4 border-purple-600 border-t-transparent rounded-full animate-spin"></div><Database className="absolute inset-0 m-auto text-purple-600 animate-pulse" size={24} /></div>
                <div className="text-center"><p className="text-lg font-bold text-slate-900 dark:text-white mb-1">Building Plan...</p><p className="text-gray-500 dark:text-gray-400 text-sm">Generating unique places for {country}</p></div>
            </div>
        ) : places.length > 0 ? (
            <div className="space-y-4">
                <div className="flex justify-between items-center">
                   <h3 className="font-bold text-lg text-slate-900 dark:text-white flex items-center gap-2"><Map size={20} className="text-purple-500" /> Top Places in {country}</h3>
                   <span className="text-sm text-gray-500 bg-white dark:bg-slate-800 px-3 py-1 rounded-full border border-gray-200 dark:border-slate-700">{places.length} results</span>
                </div>
                {calculatingDistances && (
                    <div className="text-xs text-emerald-600 dark:text-emerald-400 flex items-center gap-1.5 px-1 animate-pulse">
                        <Car size={14} /> Updating distances...
                    </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {places.map((place, idx) => {
                        const isAdded = itinerary.some(i => i.name === place.name);
                        return (
                            <div key={idx} onClick={() => handleDirections(place)} className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-all group cursor-pointer relative flex flex-col h-full">
                                <button onClick={(e) => { e.stopPropagation(); handleToggleWishlist(place, idx); }} className={`absolute top-4 right-4 p-2 rounded-full transition-colors z-10 ${isAdded ? 'bg-pink-50 text-pink-600' : 'bg-gray-50 dark:bg-slate-700 text-gray-400 hover:bg-pink-50 hover:text-pink-600'}`}>
                                    <Heart size={20} className={isAdded ? "fill-current" : ""} />
                                </button>
                                <div className="mb-2 pr-10">
                                    <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                                        <span className="px-2 py-0.5 bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-300 rounded text-[10px] font-bold uppercase tracking-wider">{place.category}</span>
                                        <span className="px-2 py-0.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-300 rounded text-[10px] font-bold uppercase tracking-wider flex items-center gap-1"><Clock size={10} /> {place.best_time_to_visit}</span>
                                    </div>
                                    <h4 className="font-bold text-lg text-slate-900 dark:text-white leading-tight">{place.name}</h4>
                                    <div className="flex items-center gap-1 mt-1 text-yellow-500">
                                        <span className="text-xs font-bold text-slate-700 dark:text-slate-300">4.5</span>
                                        <div className="flex"><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor"/><Star size={10} fill="currentColor" className="text-gray-300"/></div>
                                    </div>
                                </div>
                                <p className="text-sm text-gray-600 dark:text-gray-300 mb-4 line-clamp-2">{place.short_description}</p>
                                <div className="mt-auto">
                                    <div className="flex items-center gap-2 mb-3">
                                        <div className="flex items-center gap-2 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-900/10 rounded-lg border border-emerald-100 dark:border-emerald-900/30 w-full md:w-auto">
                                            <Navigation size={16} className="text-emerald-600 dark:text-emerald-400" />
                                            {place.distanceText ? (
                                                <span className="text-sm font-bold text-emerald-700 dark:text-emerald-400 truncate">{place.distanceText} • {place.travelTime}</span>
                                            ) : (
                                                <span className="text-xs font-medium text-gray-400 italic">
                                                    {calculatingDistances ? 'Calculating...' : 'Distance unavailable'}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap gap-3 pt-3 border-t border-gray-50 dark:border-slate-700/50">
                                        <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400"><MapPin size={12} /> {place.nearby_area}</div>
                                        <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400"><Users size={12} /> {place.ideal_for}</div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center py-20 opacity-50"><Globe className="w-16 h-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" /><p className="text-gray-500 dark:text-gray-400">Enter a country name to generate plan</p></div>
        )}
    </div>
  );
};

export const CountryGuideModal: React.FC<CountryGuideModalProps> = ({ isOpen, onClose, onAddToWishlist, onRemoveFromWishlist, itinerary, language }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[70] overflow-y-auto bg-slate-900/95 backdrop-blur-md flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-950 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl border border-gray-200 dark:border-slate-800 overflow-hidden flex flex-col animate-fade-in-up">

        {/* Header */}
        <div className="p-6 border-b border-gray-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-950 sticky top-0 z-20">
          <div className="flex items-center gap-3">
             <div className="bg-purple-600 p-2 rounded-lg shadow-lg shadow-purple-500/20">
                <Database size={24} className="text-white" />
             </div>
             <div>
               <h2 className="text-xl font-bold text-slate-900 dark:text-white">AI Country Guide</h2>
               <p className="text-xs text-gray-500 dark:text-gray-400">Generate travel plan for any country</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-full transition-colors text-gray-500">
            <X size={24} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 dark:bg-slate-900/50 p-4">
            <CountryGuideSection onAddToWishlist={onAddToWishlist} onRemoveFromWishlist={onRemoveFromWishlist} itinerary={itinerary} language={language} />
        </div>
      </div>
    </div>
  );
};
